-- Oracle user_views
CREATE OR REPLACE VIEW "iewfilf015" ("工站代碼", "製令單號", "填表日") AS (SELECT "d"."工站代碼", "e"."廠客品號" AS "製令單號", MIN("c"."填表日") AS "填表日" FROM "fil0041" AS "a" INNER JOIN "fil0040" AS "e" ON "a"."單別" = "e"."單據類別" AND "a"."單號" = "e"."單據編號" AND "a"."序號" = "e"."單據序號" INNER JOIN "fil0030" AS "c" ON "a"."單別" = "c"."單據類別" AND "a"."單號" = "c"."單據編號" INNER JOIN "fil0031" AS "d" ON "a"."單別" = "d"."單別" AND "a"."單號" = "d"."單號" WHERE "a"."單別" = 'F11' GROUP BY "d"."工站代碼", "e"."廠客品號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewa01_19_01" ("serial_num", "主檔異動日時", "pdf新增日時") AS (SELECT "a"."serial_num", CONCAT(TRIM("a"."異動日期"), TRIM("a"."異動時間")) AS "主檔異動日時", CONCAT(COALESCE(TRIM("b"."pdf新增日期"), ' '), COALESCE(TRIM("b"."pdf新增時間"), ' ')) AS "pdf新增日時" FROM "a01" AS "a" LEFT JOIN "a01_19" AS "b" ON "a"."serial_num" = "b"."serial_num");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewdoc_kmtree" ("objid", "category", "nodeid", "subject", "user_", "open2tran") AS (SELECT "doc_kmtree"."objid", "doc_kmtree"."category", "doc_kmtree"."nodeid", "doc_kmtree"."subject", "doc_kmcategory"."user_", "doc_kmtree"."open2tran" FROM "doc_kmtree", "doc_kmcategory" WHERE "doc_kmtree"."category" = "doc_kmcategory"."category");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewdoc_ownertotalsize" ("userid", "totalsize", "allowsize", "allowcategory", "allownode", "allowdoc") AS (SELECT "doc_allowedsize"."userid", ROUND(CAST(CAST(SUM(COALESCE("doc_docbytool"."blobsize", 0)) AS DOUBLE PRECISION) / 1000000 AS DECIMAL), 2) AS "totalsize", AVG(COALESCE("doc_allowedsize"."allowedsize", 0)) AS "allowsize", MAX(COALESCE("doc_allowedsize"."allowcategory", 0)) AS "allowcategory", MAX(COALESCE("doc_allowedsize"."allownode", 0)) AS "allownode", MAX(COALESCE("doc_allowedsize"."allowdoc", 0)) AS "allowdoc" FROM "doc_allowedsize" LEFT JOIN "doc_docbytool" ON "doc_docbytool"."createdby" = "doc_allowedsize"."userid" AND "doc_docbytool"."category" <> ' ' GROUP BY "doc_allowedsize"."userid");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewdoc_userrights" ("userid", "objid", "read_", "modify_", "delete_") AS (SELECT "a"."userid", "a"."objid", CASE WHEN SUM("a"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("a"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("a"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM (SELECT "a"."userid", "b"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_docbytool" AS "z" ON "b"."objid" = "z"."objid" GROUP BY "a"."userid", "b"."objid" UNION ALL /* 個人分享文件 */ SELECT "a"."userid", "a"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_docbytool" AS "z" ON "a"."objid" = "z"."objid" UNION ALL /* 群組分享頁籤 */ SELECT "a"."userid", "z"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_kmcategory" AS "y" ON "b"."objid" = "y"."category" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" GROUP BY "a"."userid", "z"."objid" UNION ALL /* 個人分享頁籤 */ SELECT "a"."userid", "z"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_kmcategory" AS "y" ON "a"."objid" = "y"."category" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" UNION ALL /* 群組分享資料夾 */ SELECT "a"."userid", "z"."objid", CASE WHEN SUM("b"."read_") = 0 THEN 0 ELSE 1 END AS "read_", CASE WHEN SUM("b"."modify_") = 0 THEN 0 ELSE 1 END AS "modify_", CASE WHEN SUM("b"."delete_") = 0 THEN 0 ELSE 1 END AS "delete_" FROM "doc_groupusers" AS "a" INNER JOIN "doc_groupobj" AS "b" ON "a"."groupid" = "b"."groupid" INNER JOIN "doc_kmtree" AS "y" ON "b"."objid" = "y"."objid" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" AND "z"."nodeid" LIKE CONCAT(RTRIM("y"."nodeid"), '%') GROUP BY "a"."userid", "z"."objid" /* 群組分享文件 */ UNION ALL /* 個人分享資料夾 */ SELECT "a"."userid", "z"."objid", "a"."read_", "a"."modify_", "a"."delete_" FROM "doc_userobj" AS "a" INNER JOIN "doc_kmtree" AS "y" ON "a"."objid" = "y"."objid" INNER JOIN "doc_docbytool" AS "z" ON "y"."category" = "z"."category" AND "z"."nodeid" LIKE CONCAT(RTRIM("y"."nodeid"), '%')) AS "a" GROUP BY "a"."userid", "a"."objid");

