CREATE OR REPLACE VIEW "viewfil0010" ("員工編號", "員工姓名", "序號", "父階", "子階", "node", "說明", "cabinet", "publicname", "啟用", "隱藏", "不需授權", "權限組合", "單據類別", "流程代碼", "特殊管制", "人事管制", "權限", "最後更新者", "最後更新日", "使用者隱藏", "獨立執行", "密碼執行") AS (SELECT "a"."員工編號", "a"."員工姓名", "a"."序號", "a"."父階", "a"."子階", "a"."node", "a"."說明", "a"."cabinet", "a"."publicname", "a"."啟用", "a"."隱藏", "a"."不需授權", "a"."權限組合", "a"."單據類別", "a"."流程代碼", "a"."特殊管制", "a"."人事管制", COALESCE("b"."權限", ' ') AS "權限", COALESCE("b"."最後更新者", ' ') AS "最後更新者", "b"."最後更新日", COALESCE("b"."隱藏", 0) AS "使用者隱藏", COALESCE("b"."獨立執行", 0) AS "獨立執行", COALESCE("b"."密碼執行", 0) AS "密碼執行" FROM (SELECT * FROM "fil1000" AS "a", "fil0010" AS "b") AS "a" LEFT JOIN "fil1007" AS "b" ON "b"."員工編號" = "a"."員工編號" AND "b"."publicname" = "a"."publicname");

