CREATE OR REPLACE VIEW "viewfil0011" ("代碼", "名稱", "廠商編號", "全名", "簡稱", "最後更新者", "更新者姓名", "最後更新日") AS (SELECT "a"."系統代碼" AS "代碼", "a"."代碼名稱" AS "名稱", "a"."文字參數" AS "廠商編號", COALESCE("b"."全名", ' ') AS "全名", COALESCE("b"."簡稱", ' ') AS "簡稱", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil1014" AS "a" LEFT JOIN "fil0011" AS "b" ON "a"."文字參數" = "b"."編號" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."代碼類別" = '公司別');

