CREATE OR REPLACE VIEW "viewfil0012" ("部門編號", "部門名稱", "英文名稱", "出勤津貼", "停止使用", "所屬公司", "所屬公司名稱", "上階部門", "製程代碼", "製程名稱", "上階部門名稱", "權責單位", "流水編號", "公司流水編號", "更新者姓名", "最後更新日") AS (SELECT "a"."部門編號", CONCAT(COALESCE("b"."名稱", ' '), '.', "a"."部門名稱") AS "部門名稱", "a"."英文名稱", "a"."出勤津貼", "a"."停止使用", "a"."所屬公司", COALESCE("b"."名稱", ' ') AS "所屬公司名稱", "a"."上階部門", "a"."製程代碼", "a"."製程名稱", COALESCE("c"."部門名稱", ' ') AS "上階部門名稱", (CASE WHEN ("a"."部門編號" BETWEEN 'A12' AND 'AZ') OR ("a"."部門編號" BETWEEN 'H12' AND 'HZ') THEN 1 ELSE 0 END) AS "權責單位", "d"."serial_num" AS "流水編號", "d"."belongto" AS "公司流水編號", COALESCE("z"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0020" AS "a" LEFT JOIN "viewfil0011" AS "b" ON "b"."代碼" = "a"."所屬公司" LEFT JOIN "fil0020" AS "c" ON "c"."部門編號" = "a"."上階部門" LEFT JOIN "fil0010" AS "z" ON "a"."最後更新者" = "z"."員工編號" LEFT JOIN "a30" AS "d" ON "d"."groupid" = "a"."部門編號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfil0012014" ("編號", "名稱", "排序", "類別") AS (SELECT "a"."部門編號" AS "編號", CONCAT(COALESCE("b"."名稱", ' '), '.', "a"."部門名稱") AS "名稱", CAST(CONCAT(COALESCE("b"."名稱", ' '), '.', "a"."部門名稱") AS TEXT) AS "排序", '1' AS "類別" FROM "fil0020" AS "a" LEFT JOIN "viewfil0011" AS "b" ON "b"."代碼" = "a"."所屬公司" UNION ALL SELECT "a"."編號", "a"."全名" AS "名稱", CAST("a"."全名" AS TEXT) AS "排序", '2' AS "類別" FROM "fil0011" AS "a" WHERE "a"."廠客" = '1');

