CREATE OR REPLACE VIEW "viewfil0013" ("寄件者", "收件者", "序號", "主旨", "本文", "提醒日", "寄件日", "寄件者姓名", "收件者姓名", "發送", "已讀", "隱藏", "通知", "簽核系統") AS (SELECT "a"."寄件者", "a"."收件者", "a"."序號", "a"."主旨", "a"."本文", "a"."提醒日", "a"."寄件日", COALESCE("b"."員工姓名", ' ') AS "寄件者姓名", COALESCE("c"."員工姓名", ' ') AS "收件者姓名", "a"."發送", "a"."已讀", "a"."隱藏", "a"."通知", "a"."簽核系統" FROM "fil1017" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."寄件者" = "b"."員工編號" LEFT JOIN "fil0010" AS "c" ON "a"."收件者" = "c"."員工編號");

