CREATE OR REPLACE VIEW "viewfil1027c" ("單據編號", "異動日期", "最後更新日", "版銅編號", "異動類別", "送修", "回廠", "來源") AS (SELECT CAST("a"."單據編號" AS TEXT) AS "單據編號", "a"."異動日期", "a"."最後更新日", CAST("a"."產品編號" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."單位代碼" = 'A' THEN '取版' ELSE '回收' END AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('1' AS TEXT) AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "c"."業務員" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C32E' AND "a"."單位代碼" BETWEEN 'A' AND 'B' UNION ALL SELECT CAST("a"."單據編號" AS TEXT) AS "單據編號", "c"."單據日期", "a"."最後更新日", CAST("a"."產品編號" AS TEXT) AS "版銅編號", CAST('送修' AS TEXT) AS "異動類別", 0 AS "送修申請", 0 AS "回廠", CAST('2' AS TEXT) AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "c"."業務員" WHERE "a"."單據類別" = 'F33' UNION ALL SELECT CAST(CONCAT("a"."版銅代碼", ':', "a"."入庫日期", "a"."入庫時間") AS TEXT) AS "單據編號", COALESCE(CASE WHEN "a"."送修" = 0 THEN "a"."入庫日期" ELSE "c"."異動日期" END, ' ') AS "異動日期", "a"."最後更新日", CAST("a"."版銅代碼" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."送修" = 0 THEN CASE WHEN POSITION('送修' IN "a"."歸屬流水編號") = 0 THEN '入庫' ELSE '入庫(送修)' END ELSE CASE WHEN "a"."回廠" = 0 THEN '出廠未回' ELSE '出廠已回' END END AS TEXT) AS "異動類別", "a"."送修", "a"."回廠", CAST('3' AS TEXT) AS "來源" FROM "fil004d" AS "a" LEFT JOIN "fil0040" AS "c" ON "c"."單據類別" = 'F33' AND "a"."歸屬流水編號" = "c"."流水編號" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" UNION ALL SELECT CONCAT(CAST("a"."版銅代碼" AS TEXT), ' ', TO_CHAR("a"."最後更新日", 'yyyymmdd'), TO_CHAR("a"."序號", '0000000000')) AS "單據編號", TO_CHAR("a"."最後更新日", 'yyyymmdd') AS "異動日期", "a"."最後更新日", CAST("a"."版銅代碼" AS TEXT) AS "版銅編號", CAST(CASE WHEN "a"."類別" = 'A' THEN '洗版開始' WHEN "a"."類別" = 'B' THEN '洗版' WHEN "a"."類別" = 'C' THEN '停用' ELSE ' ' END AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('4' AS TEXT) AS "來源" FROM "fil004e" AS "a" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" UNION ALL SELECT CONCAT(CAST("a"."歸屬代碼" AS TEXT), ' ', TO_CHAR("a"."最後更新日", 'yyyymmdd'), TO_CHAR("a"."序號", '0000000000')) AS "單據編號", TO_CHAR("a"."最後更新日", 'yyyymmdd') AS "異動日期", "a"."最後更新日", CAST("a"."歸屬代碼" AS TEXT) AS "版銅編號", CAST('調入' AS TEXT) AS "異動類別", 0 AS "送修", 0 AS "回廠", CAST('5' AS TEXT) AS "來源" FROM "fil004e" AS "a" LEFT JOIN "fil0010" AS "d" ON "d"."員工編號" = "a"."最後更新者" WHERE "a"."歸屬代碼" <> ' ');

