CREATE OR REPLACE VIEW "viewfil2011" ("單別", "單號", "最後序號") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", MAX("a"."單據序號") AS "最後序號" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" GROUP BY "a"."單據類別", "a"."單據編號");

