CREATE OR REPLACE VIEW "viewfil2023" ("單別", "單號", "序號", "類別", "logical2", "desc排序") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別" AS "類別", "a"."logical2", ROW_NUMBER() OVER (PARTITION BY "a"."單據類別", "a"."單據編號", "a"."異動類別" ORDER BY "a"."單據類別", "a"."單據編號", "a"."單據序號" DESC) AS "desc排序" FROM "fil0040" AS "a");

