CREATE OR REPLACE VIEW "viewfil2030" ("單據類別", "單據編號", "數量", "贈品量", "金額", "毛重", "材積", "製版費", "燙金費", "雷射費") AS (SELECT "a"."單據類別", "a"."單據編號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "贈品量", SUM("a"."異動金額") AS "金額", SUM("a"."毛重") AS "毛重", SUM("a"."材積") AS "材積", SUM("a"."製版費") AS "製版費", SUM("a"."燙金費") AS "燙金費", SUM("a"."雷射費") AS "雷射費" FROM "fil0040" AS "a" GROUP BY "a"."單據類別", "a"."單據編號");

