CREATE OR REPLACE VIEW "viewfil2051" ("單據類別", "單據編號", "幣別", "金額", "稅額") AS (SELECT "a"."單據類別", "a"."單據編號", "a"."幣別", SUM("a"."金額") AS "金額", SUM("a"."稅額") AS "稅額" FROM "fil0042" AS "a" GROUP BY "a"."單據類別", "a"."單據編號", "a"."幣別");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfil2061" ("單別", "單號", "序號", "異動日期", "半成品編號", "入庫米數", "捲數", "有效日期", "製造日期", "作業者", "報廢米數") AS (/* 入庫 */ SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", "a"."序號", "a"."日期一" AS "異動日期", "a"."文字一" AS "半成品編號", "a"."數字一" * CASE WHEN "a"."報廢" = 1 THEN 0 ELSE 1 END AS "入庫米數", CASE WHEN CASE WHEN "a"."報廢" = 1 THEN 0 ELSE "a"."數字一" END >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST(CASE WHEN "a"."報廢" = 1 THEN 0 ELSE "a"."數字一" END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", "f"."有效日期" AS "有效日期", CASE WHEN COALESCE("b"."交貨日期", ' ') = ' ' THEN "a"."日期二" ELSE "b"."交貨日期" END AS "製造日期", "d"."填表人" AS "作業者", 0 AS "報廢米數" FROM "fil00401" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單別" = "d"."單據類別" AND "a"."單號" = "d"."單據編號" INNER JOIN "fil0040" AS "g" ON "a"."單別" = "g"."單據類別" AND "a"."單號" = "g"."單據編號" AND "a"."序號" = "g"."單據序號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) AND "e"."加工別" = 'A' LEFT JOIN "fil003f1" AS "f" ON "f"."單據類別" = 'C11' AND "f"."單據編號" = REGEXP_SUBSTR("a"."文字一", '[^_]+', 1, 1) AND "f"."類別" = 'G1' WHERE "a"."單別" = 'C41' AND "g"."異動類別" = 'A' AND "b"."製程代碼" = 'C31D' AND "a"."文字一" <> ' ' UNION ALL /* 調整 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "單據序號", "d"."單據日期" AS "異動日期", "a"."產品編號" AS "半成品編號", "a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "入庫米數", CASE WHEN "a"."異動數量" >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST("a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", '00000000' AS "有效日期", CASE WHEN "d"."匯率日期" = ' ' THEN '00000000' ELSE "d"."匯率日期" END AS "製造日期", "a"."文數字1" AS "作業者", "a"."數值1" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "報廢米數" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) AND "e"."加工別" = 'A' WHERE "a"."單據類別" = 'E22' UNION ALL /* 調整 */ SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "單據序號", "d"."單據日期" AS "異動日期", "a"."產品編號" AS "半成品編號", "a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS "入庫米數", CASE WHEN "a"."異動數量" >= COALESCE("e"."裁切規格_m", 0) OR COALESCE("e"."裁切規格_m", 0) = 0 THEN 1 ELSE TRUNC(CAST("a"."異動數量" * CASE WHEN "a"."異動類別" = 'C' THEN -1 ELSE 1 END AS DOUBLE PRECISION) / CASE WHEN CASE WHEN POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) = 0 THEN 0 ELSE POSITION('R' IN SUBSTRING("p"."產品編號" FROM 1)) + 1 - 1 END = 0 THEN "e"."裁切規格_m" ELSE "p"."訂購數量" END, 1) END AS "捲數", '00000000' AS "有效日期", CASE WHEN "d"."匯率日期" = ' ' THEN '00000000' ELSE "d"."匯率日期" END AS "製造日期", "a"."文數字1" AS "作業者", 0 AS "報廢米數" FROM "fil0040" AS "a" /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" INNER JOIN "fil0032" AS "p" ON "p"."製令單別" = 'C11' AND "p"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) LEFT JOIN "fil0033" AS "e" ON "e"."製令單別" = 'C11' AND "e"."製令單號" = REGEXP_SUBSTR("a"."產品編號", '[^_]+', 1, 1) AND "e"."加工別" = 'A' WHERE "a"."單據類別" = 'E23');

