CREATE OR REPLACE VIEW "viewfil2067" ("單別", "單號", "製令單別", "製令單號", "加工別", "順序", "檢品編號", "前製程米數", "plc抓取米數", "合理剔除數", "不良剔除數", "線外不良剔除數", "線內不良剔除數", "檢品數量", "接頭數", "回庫數量", "生產條件米數", "備註", "耗時") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", CASE WHEN "c"."小單位" = 'A' THEN 'A材' WHEN "c"."小單位" = 'B' THEN 'B材' WHEN "c"."小單位" = 'C' THEN '底邊' WHEN "c"."小單位" = 'D' THEN 'A側' WHEN "c"."小單位" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", MIN("a"."單據序號") AS "順序", MAX("a"."產品編號") AS "檢品編號", SUM("a"."異動數量") AS "前製程米數", SUM("a"."異動單價") AS "plc抓取米數", SUM("a"."燙金費") AS "合理剔除數", SUM("a"."毛重") AS "不良剔除數", SUM("a"."雷射費") AS "線外不良剔除數", SUM("a"."夾鏈費") AS "線內不良剔除數", SUM("a"."贈品數量") AS "檢品數量", SUM("a"."折扣率") AS "接頭數", MAX(COALESCE("e"."回庫數量", 0)) AS "回庫數量", MAX(COALESCE("d"."印刷米數", 0) * 1000) AS "生產條件米數", STRING_AGG(CAST(COALESCE(TRIM("c"."文字1"), ' ') AS TEXT), ' ' ORDER BY "a"."單據序號") AS "備註", SUM("a"."qrno") AS "耗時" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN (SELECT "f"."製令單別", "f"."製令單號", SUM("f"."印刷米數") AS "印刷米數" FROM "fil0033" AS "f" WHERE "f"."印刷基材" <> ' ' GROUP BY "f"."製令單別", "f"."製令單號") AS "d" ON "d"."製令單別" = "a"."前置單別" AND "d"."製令單號" = "a"."前置單號" LEFT JOIN (SELECT "a"."單據類別", "a"."單據編號", "a"."前置單號" AS "製令單號", "a"."單位代碼" AS "加工別", SUM("a"."贈品數量") AS "回庫數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'G' AND "b"."製程代碼" = 'C31H' AND "c"."標籤列印次數" > 0 GROUP BY "a"."單據類別", "a"."單據編號", "a"."前置單號", "a"."單位代碼") AS "e" ON "e"."單據類別" = "a"."單據類別" AND "e"."單據編號" = "a"."單據編號" AND "a"."前置單號" = "e"."製令單號" AND "a"."單位代碼" = "e"."加工別" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程