CREATE OR REPLACE VIEW "viewfil402b" ("單別", "單號", "產品編號", "報價數量", "訂單數量", "未訂購數", "報價金額", "訂單金額") AS (SELECT COALESCE("a"."單據類別", "b"."歸屬類別") AS "單別", COALESCE("a"."單據編號", "b"."歸屬編號") AS "單號", COALESCE("a"."產品編號", "b"."產品編號") AS "產品編號", COALESCE("a"."報價數量", 0) AS "報價數量", COALESCE("b"."訂單數量", 0) AS "訂單數量", COALESCE("a"."報價數量", 0) - COALESCE("b"."訂單數量", 0) AS "未訂購數", COALESCE("a"."報價金額", 0) AS "報價金額", COALESCE("b"."訂單金額", 0) AS "訂單金額" FROM (/* 報價單 */ SELECT "a"."單據類別", "a"."單據編號", "a"."產品編號", SUM("a"."異動數量") AS "報價數量", SUM("a"."異動金額" + "a"."製版費" + "a"."燙金費" + "a"."雷射費") AS "報價金額" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'B11' GROUP BY "a"."單據類別", "a"."單據編號", "a"."產品編號") AS "a" FULL OUTER JOIN (/* 訂單 */ SELECT "b"."歸屬類別", "b"."歸屬編號", "a"."產品編號", SUM("a"."異動數量") AS "訂單數量", SUM("a"."異動金額") AS "訂單金額" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" WHERE "a"."單據類別" = 'B31' GROUP BY "b"."歸屬類別", "b"."歸屬編號", "a"."產品編號") AS "b" ON "a"."單據類別" = "b"."歸屬類別" AND "a"."單據編號" = "b"."歸屬編號" AND "a"."產品編號" = "b"."產品編號");

