' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" WHERE "a"."單據類別" BETWEEN 'E32' AND 'E37' UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."廠客品號" AS "製令單號", "a"."異動數量" AS "箱號", "a"."贈品數量" AS "數量", 0 AS "報廢數量", "c"."批號", 0 AS "製袋", 0 AS "氣閥", 0 AS "鐵條", 1 AS "異動", 0 AS "重工", 0 AS "出貨", 0 AS "品檢", TO_NCHAR('盤點') FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '1' AND /* 半成品 */ "b"."稅別" = 'B' /* 廠內 */);

