CREATE OR REPLACE VIEW "viewfil404e4_t1" ("批號", "數量") AS (SELECT "a"."批號", SUM("a"."數量") AS "數量" FROM (SELECT CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(CASE WHEN "c"."製程代碼" = 'C31E' THEN COALESCE(CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END, 0) WHEN "c"."製程代碼" = 'C31F' THEN COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0) WHEN "c"."製程代碼" = 'C31G' THEN COALESCE(("b"."數值5" + "a"."燙金費") * -1, 0) ELSE 0 END) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b", "fil0031" AS "c", "fil0030" AS "d" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" AND "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "c"."製程代碼" BETWEEN 'C31E' AND 'C31G' GROUP BY CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) UNION ALL SELECT CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009'))) AS "批號", SUM(CASE WHEN "a"."單據類別" = 'E32' THEN COALESCE("a"."贈品數量", 0) WHEN "a"."單據類別" = 'E33' THEN COALESCE("a"."贈品數量", 0) + COALESCE("b"."數值5", 0) WHEN "a"."單據類別" = 'E37' THEN COALESCE("b"."數值5" * -1, 0) ELSE 0 END) AS "數量" FROM "fil0040" AS "a", "fil0041" AS "b" WHERE ("a"."單據類別" = 'E32' OR "a"."單據類別" = 'E33' OR "a"."單據類別" = 'E37') AND "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" GROUP BY CONCAT("a"."廠客品號", '-', TRIM(TO_CHAR("a"."異動數量", '0009')))) AS "a" GROUP BY "a"."批號");

