 WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN "a"."贈品數量" ELSE 0 END ELSE 0 END) AS "繳庫袋數", SUM(CASE WHEN "a"."贈品數量" = CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN 1 ELSE 0 END ELSE 0 END) AS "繳庫袋數_箱數", SUM(CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END END ELSE 0 END) AS "尾數成品", SUM(CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END) AS "尾數成品_箱數" /* 有尾數成品且結束則1箱 */, SUM(CASE WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "a"."贈品數量" END END ELSE 0 END) AS "尾數成品二", SUM(CASE WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END) AS "尾數成品二_箱數", SUM(CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END) AS "繳庫總袋數", SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "c"."數值14" = 0 THEN "a"."贈品數量" ELSE "c"."數值14" END ELSE 0 END) AS "待重工總袋數", (SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "a"."贈品數量" = CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END OR ("a"."贈品數量" IS NULL AND CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN "a"."贈品數量" /* 非雙膜數量全計 */ ELSE CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END END ELSE "a"."贈品數量" /* 非末一二筆數量全計 */ END IS NULL) THEN CASE WHEN "c"."數值14" /* 補尾數 */ = 0 THEN 1 ELSE 0 END ELSE 0 END ELSE 0 END) + SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "c"."數值14" = 0 THEN 0 ELSE 1 END ELSE 0 END) + SUM(CASE WHEN "a"."logical3" = 1 THEN CASE WHEN "a"."單據序號" = "d"."序號" /* 末一筆 */ OR ("a"."單據序號" IS NULL AND "d"."序號" /* 末一筆 */ IS NULL) THEN CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END WHEN "a"."單據序號" = "e"."序號" /* 末二筆 */ OR ("a"."單據序號" IS NULL AND "e"."序號" /* 末二筆 */ IS NULL) THEN CASE WHEN "d"."logical2" /* 雙膜 */ = 0 THEN 0 ELSE CASE WHEN "a"."贈品數量" = CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END OR ("a"."贈品數量" IS NULL AND CASE WHEN "c"."logical5" = 0 THEN "b"."數值17" ELSE "b"."數值19" END IS NULL) THEN 0 ELSE "b"."logical4" END END ELSE 0 END ELSE 0 END)) AS "待重工總箱數", SUM("c"."數值19") AS "a材退庫", SUM("c"."數值20") AS "b材退庫", SUM("c"."數值21") AS "側邊退庫", SUM("c"."數值22") AS "底邊退庫" /*
			B.數值17 紙箱_無氣閥_每箱幾袋
