			*/ FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "a"."單據類別" = "m"."單據類別" AND "a"."單據編號" = "m"."單據編號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "viewfil2023" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "d"."類別" = 'A' AND "d"."desc排序" = 1 LEFT JOIN "viewfil2023" AS "e" ON "a"."單據類別" = "e"."單別" AND "a"."單據編號" = "e"."單號" AND "e"."類別" = 'A' AND "e"."desc排序" = 2 WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "b"."製程代碼" = 'C31E' GROUP BY "a"."單據類別", "a"."單據編號") AS "a" INNER JOIN "fil0030" AS "b" ON "b"."單據類別" = "a"."單別" AND "a"."單號" = "b"."單據編號" INNER JOIN "fil0031" AS "c" ON "a"."單別" = "c"."單別" AND "a"."單號" = "c"."單號" INNER JOIN "fil0032" AS "e" ON "e"."製令單別" = "b"."歸屬類別" AND "e"."製令單號" = "b"."歸屬編號");

