CREATE OR REPLACE VIEW "viewfil404ee" ("單號", "作業日期", "工作時數", "類別") AS (SELECT "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CAST((86400 - (TO_NUMBER(ORA_SUBSTR("b"."時間一", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 5, 6)))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '1' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" > "b"."時間二" UNION SELECT "a"."單據編號" AS "單號", TO_CHAR(TO_DATE("a"."單據日期", 'yyyymmdd') + 1, 'yyyymmdd') AS "作業日期", CAST((TO_NUMBER(ORA_SUBSTR("b"."時間二", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 5, 6))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '2' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" > "b"."時間二" UNION SELECT "a"."單據編號" AS "單號", "a"."單據日期" AS "作業日期", CAST(((TO_NUMBER(ORA_SUBSTR("b"."時間二", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間二", 5, 6))) - (TO_NUMBER(ORA_SUBSTR("b"."時間一", 1, 2)) * 60 * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 3, 2)) * 60 + TO_NUMBER(ORA_SUBSTR("b"."時間一", 5, 6)))) AS DOUBLE PRECISION) / 3600 AS "工作時數", '3' AS "類別" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "b"."時間一" < "b"."時間二");

