CREATE OR REPLACE VIEW "viewfile03e" ("批號", "結存數量", "製袋重量", "生產日期", "氣閥重量", "鐵條重量", "紙箱重量", "箱號異動", "重工", "品檢", "製袋平均重量", "氣閥平均重量", "鐵條平均重量") AS (SELECT "a"."批號", ROUND(COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0)) AS "結存數量", ROUND(COALESCE("c"."製袋平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "製袋重量", COALESCE("c"."生產日期", ' ') AS "生產日期", ROUND(COALESCE("d"."氣閥平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "氣閥重量", ROUND(COALESCE("e"."鐵條平均重量" * COALESCE(CASE WHEN "b"."結存數量" < 0 THEN 0 ELSE "b"."結存數量" END, 0), 0), 2) AS "鐵條重量", ROUND(COALESCE("f"."紙箱重量", 0), 2) AS "紙箱重量", CASE WHEN COALESCE("g"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "箱號異動", CASE WHEN COALESCE("h"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "重工", CASE WHEN COALESCE("i"."筆數", 0) = 0 THEN 0 ELSE 1 END AS "品檢", COALESCE("c"."製袋平均重量", 0) AS "製袋平均重量", COALESCE("d"."氣閥平均重量", 0) AS "氣閥平均重量", COALESCE("e"."鐵條平均重量", 0) AS "鐵條平均重量" FROM "viewfil404e4_t8" AS "a" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "結存數量" FROM "fil004l" AS "a") AS "b" ON "b"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."異動日期") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" ASC) AS "生產日期", FIRST_VALUE(CAST("a"."製袋重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "製袋平均重量" FROM "fil004l" AS "a" WHERE "a"."製袋重量" > 0 AND "a"."數量" > 0) AS "c" ON "c"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE(CAST("a"."氣閥重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "氣閥平均重量" FROM "fil004l" AS "a" WHERE "a"."氣閥重量" > 0 AND "a"."數量" > 0) AS "d" ON "d"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE(CAST("a"."鐵條重量" AS DOUBLE PRECISION) / "a"."數量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "鐵條平均重量" FROM "fil004l" AS "a" WHERE "a"."鐵條重量" > 0 AND "a"."數量" > 0) AS "e" ON "e"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", FIRST_VALUE("a"."紙箱重量") OVER (PARTITION BY "a"."批號" ORDER BY "a"."最後更新日時" DESC) AS "紙箱重量" FROM "fil004l" AS "a" WHERE "a"."紙箱重量" > 0 AND "a"."數量" > 0) AS "f" ON "f"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '異動' GROUP BY "a"."批號") AS "g" ON "g"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '重工' GROUP BY "a"."批號") AS "h" ON "h"."批號" = "a"."批號" LEFT JOIN (SELECT DISTINCT "a"."批號", COUNT("a"."批號") AS "筆數" FROM "fil004l" AS "a" WHERE "a"."來源" = '品檢' GROUP BY "a"."批號") AS "i" ON "i"."批號" = "a"."批號");

