CREATE OR REPLACE VIEW "viewfilh005c" ("單別", "單號", "序號", "氣閥日報", "氣閥產量", "申請人代號", "申請人姓名", "加班日期", "單據加班時數", "製令單號") AS WITH "tmp1" AS (SELECT "a"."製令單別" AS "單別", "a"."製令單號" AS "單號", "a"."材料序號" AS "序號", "a"."相關單號" AS "氣閥日報", SUM("a"."數字一") AS "氣閥產量" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "b" ON "b"."單別" = "a"."相關單別" AND "b"."單號" = "a"."相關單號" WHERE "a"."製令單別" = 'H03' AND "a"."屬性" = '4' AND "a"."相關單別" = 'C41' AND "b"."製程代碼" = 'C31F' GROUP BY "a"."製令單別", "a"."製令單號", "a"."材料序號", "a"."相關單號"), "tmp2" AS (SELECT "a1"."單據類別" AS "單別", "a1"."單據編號" AS "單號", "a1"."單據序號" AS "序號", "a1"."產品編號" AS "申請人代號", CASE WHEN "a1"."異動日期" = '00000000' THEN "b1"."單據日期" ELSE "a1"."異動日期" END AS "加班日期", COALESCE("e1"."員工姓名", ' ') AS "申請人姓名", "a1"."贈品數量" - "a1"."異動單價" - "a1"."異動金額" AS "單據加班時數" FROM "fil0040" AS "a1" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b1" ON "a1"."單據類別" = "b1"."單據類別" AND "a1"."單據編號" = "b1"."單據編號" LEFT JOIN "fil0010" AS "e1" ON "a1"."產品編號" = "e1"."員工編號" WHERE "a1"."單據類別" = 'H03') SELECT "a"."單別", "a"."單號", "a"."序號", "a"."氣閥日報", "a"."氣閥產量", "b"."申請人代號", "b"."申請人姓名", "b"."加班日期", "b"."單據加班時數", "c"."歸屬編號" AS "製令單號" FROM "tmp1" AS "a" INNER JOIN "tmp2" AS "b" ON "a"."單別" = "b"."單別" AND "a"."單號" = "b"."單號" AND "a"."序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "c"."單據類別" = 'C41' AND "c"."單據編號" = "a"."氣閥日報";

