CREATE OR REPLACE VIEW "viewfilh006" ("單別", "單號", "數量", "時數", "申請人") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", COALESCE("m"."數量", 0) AS "數量", COALESCE("m"."時數", 0) AS "時數", COALESCE("m"."申請人", ' ') AS "申請人" FROM "fil0030" AS "a" LEFT JOIN (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "數量", SUM("a"."贈品數量") AS "時數", "utl_raw".cast_to_nvarchar2(STRING_AGG(CAST(CONCAT("utl_raw".cast_to_raw(CONCAT("b"."員工姓名", '[')), "utl_raw".cast_to_raw(TRIM(TO_NCHAR(ROUND("a"."贈品數量" - "a"."異動單價" - "a"."異動金額", 1), '90D9'))), "utl_raw".cast_to_raw(N'小時]')) AS TEXT), "utl_raw".cast_to_raw(N',') ORDER BY "a"."單據類別", "a"."單據編號")) AS "申請人" FROM "fil0040" AS "a" LEFT JOIN "fil0010" AS "b" ON "a"."產品編號" = "b"."員工編號" WHERE "a"."單據類別" = 'H03' GROUP BY "a"."單據類別", "a"."單據編號") AS "m" ON "m"."單別" = "a"."單據類別" AND "m"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H03');

