CREATE OR REPLACE VIEW "viewfilh006a" ("申請人", "加班日期", "筆數") AS (SELECT "a"."產品編號" AS "申請人", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END AS "加班日期", COUNT("a"."單據序號") AS "筆數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'H03' AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號", CASE WHEN "a"."異動日期" = '00000000' THEN "b"."單據日期" ELSE "a"."異動日期" END);

