S "假日前8小時", SUM("a"."例假日大於8小時") AS "例假日大於8小時", SUM("a"."例假日大於10小時") AS "例假日大於10小時", SUM("a"."例假日補休小時") AS "例假日補休小時", SUM("a"."國定假日前8小時") AS "國定假日前8小時", SUM("a"."國定假日大於8小時") AS "國定假日大於8小時", SUM("a"."國定假日大於10小時") AS "國定假日大於10小時" FROM "hrfil2006" AS "a" LEFT JOIN "hrfil1002a" AS "b" ON "b"."syskey" = 'EMP' WHERE ORA_SUBSTR("a"."年月", 1, 6) <= ORA_SUBSTR("b"."關帳年月", 1, 6) GROUP BY ORA_SUBSTR("a"."年月", 1, 4), "a"."員工編號");

