CREATE OR REPLACE VIEW "viewfilm000s" ("條碼", "目前庫位") AS (SELECT DISTINCT "條碼", LAST_VALUE("庫位") OVER (PARTITION BY "條碼" ORDER BY "序號" RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS "目前庫位" FROM "fil0044" WHERE "條碼" <> ' ' AND "庫位" <> ' ');

