CREATE OR REPLACE VIEW "viewfilm008h_wk" ("製令單別", "製令單號", "加工別", "製程代碼", "半成品編號", "庫存數") AS (SELECT CAST('C11' AS TEXT) AS "製令單別", REGEXP_SUBSTR("a"."批號", '[^_]+', 1) AS "製令單號", REGEXP_SUBSTR("a"."批號", '[A-Z]+', 1) AS "加工別", REGEXP_SUBSTR("a"."批號", '[A-Z][0-9][0-9][A-Z]') AS "製程代碼", "a"."批號" AS "半成品編號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."批號", "a"."異動數" FROM "wkfilm018h" AS "a") AS "a" GROUP BY CAST('C11' AS TEXT), REGEXP_SUBSTR("a"."批號", '[^_]+', 1), REGEXP_SUBSTR("a"."批號", '[A-Z]+', 1), REGEXP_SUBSTR("a"."批號", '[A-Z][0-9][0-9][A-Z]'), "a"."批號");

