CREATE OR REPLACE VIEW "viewfilm008s_wk" ("材料編號", "品名", "規格", "庫存數") AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫存數" FROM (SELECT "f"."料號", SUM(COALESCE("a"."庫存數", 0)) AS "庫存數" FROM "wkfilm017s" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" GROUP BY "f"."料號") AS "a" INNER JOIN "fil0012" AS "e" ON "e"."產品編號" = "a"."料號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm016" ("批號", "庫存數") AS (SELECT "a"."批號", SUM("a"."異動數") AS "庫存數" FROM (SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * "b"."材料庫存參數" AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 單位換算
			LEFT JOIN FIL0012 E ON A.產品編號 = E.產品編號
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ WHERE "c"."批號" <> ' ' UNION ALL /* 發料 */ SELECT "c"."批號", "a"."異動數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 單位換算
			LEFT JOIN FIL0012 G ON A.產品編號 = G.產品編號
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
			*/ WHERE "a"."單據類別" = 'C4M' AND "c"."批號" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "b"."批號", "a"."異動數量" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 單位換算
			LEFT JOIN FIL0012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "b"."文數字1" AS "批號", "b"."數值1" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "b"."文數字2" AS "批號", "b"."數值2" * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' UNION ALL /* 發料回庫(+) */ SELECT "b"."批號", "a"."贈品數量" * 1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" /* 單位換算
			LEFT JOIN FIL0012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 /* 廠內盤點調整 */ UNION ALL SELECT "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2') AS "a" GROUP BY "a"."批號");

