CREATE OR REPLACE VIEW "viewfilm018a" ("單據類別", "單據編號", "單據序號", "製程代碼", "異動類別", "單據日期", "批號", "最後更新日", "異動數") AS (/* A材 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字1" AS "批號", "a"."最後更新日", ("c"."數值1" - "c"."數值19") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字1" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字1" <> ' ' UNION ALL /* B材 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字2" AS "批號", "a"."最後更新日", ("c"."數值2" - "c"."數值20") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字2" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字2" <> ' ' UNION ALL /* 側邊 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."製程代碼", "a"."異動類別", "a"."異動日期" AS "單據日期", "c"."文數字3" AS "批號", "a"."最後更新日", ("c"."數值3" - "c"."數值21") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字3" WHERE "a"."單據類別" = 'C41' AND "b"."製程代碼" = 'C31E' AND "c"."文數字3" <> ' ' UNION ALL /* 底邊 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."製程代碼", "a"."異動日期" AS "單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", ("c"."數值4" - "c"."數值22") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號