CREATE OR REPLACE VIEW "viewfilm018sa" ("請領單別", "請領單號", "料號", "請領數量", "發料數量", "日報領用數量", "日報退庫數量", "日報沿用數量") AS WITH "tmp1" AS (/* 請領發料 */ SELECT "a"."請領單別", "a"."請領單號", "a"."料號", SUM("a"."核准數量") AS "核准數量", SUM("a"."發料數量") AS "發料數量" FROM (SELECT CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據類別" ELSE "b"."歸屬類別" END AS "請領單別", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."單據編號" ELSE "b"."歸屬編號" END AS "請領單號", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."產品編號" ELSE "a"."文數字1" END AS "料號", CASE WHEN "a"."單據類別" = 'C4L' THEN "a"."異動數量" ELSE 0 END * "b"."邏輯值一" AS "核准數量", CASE WHEN "a"."單據類別" = 'C4M' THEN "a"."異動數量" ELSE 0 END AS "發料數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "fil0041" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" AND "a"."單據序號" = "d"."序號" WHERE "a"."單據類別" BETWEEN 'C4L' AND 'C4M') AS "a" GROUP BY "a"."請領單別", "a"."請領單號", "a"."料號"), "tmp2" /* 日報領用 */ AS (SELECT 'C4L' AS "請領單別", "e"."其它單號" AS "請領單號", "e"."請領料號" AS "料號", SUM("a"."異動數量") AS "領用數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0044" AS "e" ON "e"."條碼" = CAST("c"."文數字4" AS TEXT) AND "e"."單據類別" = 'C4M' AND "e"."來源" = 'O' WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' GROUP BY "e"."其它單號", "e"."請領料號"), "tmp2a" /* 裁切領用 */ AS (SELECT 'C4L' AS "請領單別", "e"."其它單號" AS "請領單號", "e"."請領料號" AS "料號", SUM("a"."折讓") AS "領用數量" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0044" AS "e" ON "e"."條碼" = "a"."廠客單號" AND "e"."單據類別" = 'C4M' AND "e"."來源" = 'O' WHERE "a"."單據類別" = 'E13' AND "a"."折讓" > 0 AND "a"."廠客單號" <> ' ' GROUP BY "e"."其它單號", "e"."請領料號"), "tmp3" /* 日報退回 */ AS (SELECT 'C4L' AS "請領單別", "e"."其它單號" AS "請領單號", "e"."請領料號" AS "料號", SUM("a"."退庫數量" * CASE WHEN "a"."logical1" = 1 THEN 0 ELSE 1 END) AS "退庫數量", SUM("a"."退庫數量" * "a"."logical1") AS "沿用數量" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0044" AS "e" ON "e"."條碼" = CAST("c"."文數字4" AS TEXT) AND "e"."單據類別" = 'C4M' AND "e"."來源" = 'O' WHERE "a"."單據類別" = 'C41' AND "a"."退庫數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' GROUP BY "e"."其它單號", "e"."請領料號"), "tmp3a" /* 裁切退回 */ AS (SELECT 'C4L' AS "請領單別", "e"."其它單號" AS "請領單號", "e"."請領料號" AS "料號", SUM("d"."數值1") AS "退庫數量" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0044" AS "e" ON "e"."條碼" = "a"."廠客單號" AND "e"."單據類別" = 'C4M' AND "e"."來源" = 'O' INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'E13' AND "d"."數值1" > 0 AND "a"."廠客單號" <> ' ' GROUP BY "e"."其它單號", "e"."請領料號") SELECT "a"."請領單別", "a"."請領單號", "a"."料號", SUM("a"."核准數量") AS "請領數量", SUM("a"."發料數量") AS "發料數量", SUM(CAST((COALESCE("b"."領用數量", 0) + COALESCE("d"."領用數量", 0)) AS DOUBLE PRECISION) / 1000) AS "日報領用數量", SUM(CAST((COALESCE("c"."退庫數量", 0) + COALESCE("e"."退庫數量", 0)) AS DOUBLE PRECISION) / 1000) AS "日報退庫數量", SUM(CAST(COALESCE("c"."沿用數量", 0) AS DOUBLE PRECISION) / 1000) AS "日報沿用數量" FROM "tmp1" AS "a" LEFT JOIN "tmp2" AS "b" ON "b"."請領單別" = "a"."請領單別" AND "b"."請領單號" = "a"."請領單號" AND "b"."料號" = "a"."料號" LEFT JOIN "tmp3" AS "c" ON "c"."請領單別" = "a"."請領單別" AND "c"."請領單號" = "a"."請領單號" AND "c"."料號" = "a"."料號" LEFT JOIN "tmp2a" AS "d" ON "d"."請領單別" = "a"."請領單別" AND "d"."請領單號"