"a"."單據編號" = "b"."單號" LEFT JOIN "viewfilhs02" AS "w" ON ORA_SUBSTR("w"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "w"."員工編號" = "a"."業務員" LEFT JOIN "viewfilhs02" AS "x" ON ORA_SUBSTR("x"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "x"."員工編號" = "b"."文數字10" LEFT JOIN "viewfilhs02" AS "y" ON ORA_SUBSTR("y"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "y"."員工編號" = "b"."文數字11" LEFT JOIN "viewfilhs02" AS "z" ON ORA_SUBSTR("z"."年月", 1, 6) = ORA_SUBSTR("a"."單據日期", 1, 6) AND "z"."員工編號" = "b"."文數字12" WHERE "a"."單據類別" = 'C41' AND "a"."單據日期" > '2025' AND ("b"."製程代碼" = 'C31H' OR "b"."製程代碼" = 'C31K') GROUP BY ORA_SUBSTR("a"."單據日期", 1, 6), "b"."製程代碼") SELECT "a"."年月", "a"."製程代碼", "a"."實際直接人工", COALESCE("b"."分攤直接人工", 0) AS "分攤直接人工" FROM "temp1" AS "a" LEFT JOIN (SELECT "a"."年月", "a"."製程代碼", SUM(CASE WHEN "a"."成本類別" = 'A' THEN ("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") ELSE 0 END) AS "分攤直接人工" FROM "viewfilhs02" AS "a" GROUP BY "a"."年月", "a"."製程代碼") AS "b" ON ORA_SUBSTR("a"."年月", 1, 6) = ORA_SUBSTR("b"."年月", 1, 6) AND "a"."製程代碼" = "b"."製程代碼";

