CREATE OR REPLACE VIEW "viewfilr002" ("單別", "單號", "序號", "製令單別", "製令單號", "產品編號", "產品名稱", "產品規格", "材質結構", "交貨備註", "異常備註", "成品規格", "交貨日期", "交貨數量", "異常數量", "單位代碼", "單位名稱", "異常單位代碼", "異常單位名稱", "客戶編號", "流水編號", "最後更新者", "更新者姓名", "最後更新日") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "a"."產品編號", COALESCE("e"."客戶報價品名", ' ') AS "產品名稱", COALESCE("e"."客戶報價規格", ' ') AS "產品規格", COALESCE("e"."文數字4", ' ') AS "材質結構", COALESCE("e"."文字1", ' ') AS "交貨備註", COALESCE("e"."文字2", ' ') AS "異常備註", COALESCE("d"."規格", ' ') AS "成品規格", "a"."異動日期" AS "交貨日期", "a"."異動數量" AS "交貨數量", "a"."贈品數量" AS "異常數量", "a"."單位代碼" AS "單位代碼", COALESCE("f1"."名稱", ' ') AS "單位名稱", "a"."倉庫代碼" AS "異常單位代碼", COALESCE("f1"."名稱", ' ') AS "異常單位名稱", "c"."廠客編號" AS "客戶編號", "a"."流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0032" AS "b" ON "a"."前置單別" = "b"."製令單別" AND "a"."前置單號" = "b"."製令單號" INNER JOIN "fil0030" AS "c" ON "a"."前置單別" = "c"."單據類別" AND "a"."前置單號" = "c"."單據編號" LEFT JOIN "fil0012" AS "d" ON "b"."產品編號" = "d"."產品編號" LEFT JOIN "fil0041" AS "e" ON "a"."單據類別" = "e"."單別" AND "a"."單據編號" = "e"."單號" AND "a"."單據序號" = "e"."序號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."倉庫代碼" = "f2"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'R01' AND "a"."單據編號" <> ' ');

