CREATE OR REPLACE VIEW "viewfilr012" ("單別", "單號", "生產總量", "異常數量", "不良率", "待確認筆數", "單位不同", "總產量單位") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", SUM("a"."異動數量") AS "生產總量", SUM(CASE WHEN "a"."logical3" = 0 THEN "a"."贈品數量" END) AS "異常數量", CASE WHEN SUM("a"."異動數量") = 0 THEN 0 ELSE ROUND(CAST(SUM(CASE WHEN "a"."logical3" = 0 THEN "a"."贈品數量" END) AS DOUBLE PRECISION) / SUM("a"."異動數量") * 100, 3) END AS "不良率", SUM(CASE WHEN "a"."logical3" = 1 THEN 1 ELSE 0 END) AS "待確認筆數", SUM(CASE WHEN "a"."單位代碼" = CAST("a"."相關代碼1" AS TEXT) OR "a"."相關代碼1" = ' ' THEN 0 ELSE 1 END) AS "單位不同", ' ' AS "總產量單位" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'R02' GROUP BY "a"."單據類別", "a"."單據編號");

