CREATE OR REPLACE VIEW "viewofflowdetail" ("type", "serialno", "empserialno", "folderstatus", "flowstatus", "signorcc", "itemno") AS SELECT 'A', "a01"."serial_num", "a01"."applyby", "a01"."flowstatus", 'A', 1, 0 FROM "a01" UNION /* 單據屬性:開單人 */ SELECT 'B', "a01"."serial_num", "a01"."owner", "a01"."flowstatus", 'A', 1, 0 FROM "a01" UNION /* 單據流程:應簽 */ SELECT 'C', "a"."serial_num", "a"."assignedto", "b"."flowstatus", (CASE WHEN "a"."signedtype" = '2' THEN 'R' WHEN "a"."signedtype" = '1' THEN 'A' ELSE 'I' END), "a"."signorcc", "a"."serial_num_seq" FROM "a01_2" AS "a" INNER JOIN "a01" AS "b" ON "a"."serial_num" = "b"."serial_num" LEFT JOIN "a01_2" AS "c" ON "a"."serial_num" = "c"."serial_num" AND "a"."version" = "c"."serial_num_seq" UNION /* 單據流程:簽核 */ SELECT 'D', "a01_2"."serial_num", "a01_2"."signedby", "a01"."flowstatus", (CASE WHEN "a01_2"."signedtype" = '2' THEN 'R' WHEN "a01_2"."signedtype" = '1' THEN 'A' ELSE 'I' END), "a01_2"."signorcc", "a01_2"."serial_num_seq" FROM "a01_2", "a01" WHERE "a01_2"."serial_num" = "a01"."serial_num" AND "a01_2"."signedby" <> ' ' AND "a01_2"."assignedto" <> "a01_2"."signedby" UNION /* 單據流程:退簽 */ SELECT 'E', "a"."serial_num", "a"."signbackto", "b"."flowstatus", (CASE WHEN "a"."signedtype" = '2' THEN 'R' WHEN "a"."signedtype" = '1' THEN 'A' ELSE 'I' END), "a"."signorcc", "a"."serial_num_seq" FROM "a01_2" AS "a" INNER JOIN "a01" AS "b" ON "a"."serial_num" = "b"."serial_num" LEFT JOIN "a01_2" AS "c" ON "a"."serial_num" = "c"."serial_num" AND "a"."version" = "c"."serial_num_seq";

