CREATE OR REPLACE VIEW "viewdoc_sharefolder" ("createdby", "parentid", "文件夾", "userid") AS (SELECT DISTINCT CAST(' ' AS VARCHAR(100)) AS "createdby", CAST(' ' AS VARCHAR(100)) AS "parentid", CAST('分享文件' AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_kmtree" AS "c" ON "b"."category" = "c"."category" AND "b"."nodeid" = "c"."nodeid" INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' UNION ALL SELECT DISTINCT CAST('分享文件' AS VARCHAR(100)) AS "createdby", CAST('分享文件' AS VARCHAR(100)) AS "parentid", CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_kmtree" AS "c" ON "b"."category" = "c"."category" AND "b"."nodeid" = "c"."nodeid" INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' LEFT JOIN "viewfil1010" AS "e" ON "b"."createdby" = "e"."員工編號" UNION ALL SELECT DISTINCT CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "createdby", CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "parentid", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 2)) AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' LEFT JOIN "viewfil1010" AS "e" ON "b"."createdby" = "e"."員工編號" UNION ALL SELECT DISTINCT CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "createdby", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 2)) AS VARCHAR(100)) AS "parentid", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 5)) AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' LEFT JOIN "viewfil1010" AS "e" ON "b"."createdby" = "e"."員工編號" WHERE LENGTH(TRIM("b"."nodeid")) > 2 UNION ALL SELECT DISTINCT CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "createdby", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 5)) AS VARCHAR(100)) AS "parentid", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 8)) AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' LEFT JOIN "viewfil1010" AS "e" ON "b"."createdby" = "e"."員工編號" WHERE LENGTH(TRIM("b"."nodeid")) > 5 UNION ALL SELECT DISTINCT CAST(COALESCE("e"."員工姓名", "b"."createdby") AS VARCHAR(100)) AS "createdby", CAST(CONCAT("b"."category", '#', ORA_SUBSTR("b"."nodeid", 1, 8)) AS VARCHAR(100)) AS "parentid", CAST(CONCAT("b"."category", '#', "b"."nodeid") AS VARCHAR(100)) AS "文件夾", "a"."userid" FROM "viewdoc_userrights" AS "a" INNER JOIN "doc_docbytool" AS "b" ON "a"."objid" = "b"."objid" AND "b"."deleted" = 0 INNER JOIN "doc_jobstatus" AS "d" ON "a"."objid" = "d"."objid" AND "d"."status" = 'U' LEFT JOIN "viewfil1010" AS "e" ON "b"."createdby" = "e"."員工編號" WHERE LENGTH(TRIM("b"."nodeid")) > 8);

