CREATE OR REPLACE VIEW "viewfil4042" ("製令單號", "節點", "製程代碼", "ab底側", "ab底側二", "ab底側三", "ab底側四", "使用半成品", "使用半成品二", "使用半成品三", "使用半成品四", "物料編號", "物料編號二", "物料編號三", "物料編號四", "工作代碼", "預計投產日", "實際投產日", "名稱", "父節點", "說明", "半成品名稱") AS (SELECT "m"."製令單號", "m"."節點", "m"."製程代碼", "m"."ab底側", "m"."ab底側二", "m"."ab底側三", "m"."ab底側四", "m"."使用半成品", "m"."使用半成品二", "m"."使用半成品三", "m"."使用半成品四", "m"."物料編號", "m"."物料編號二", "m"."物料編號三", "m"."物料編號四", "m"."工作代碼", "m"."預計投產日", "m"."實際投產日", REPLACE(CONCAT(CASE WHEN "m"."製程代碼" = 'C32A' THEN '燙金' WHEN "m"."製程代碼" = 'C32B' THEN '數位噴墨' WHEN "m"."製程代碼" = 'C32C' THEN '品檢' WHEN "m"."製程代碼" = 'C32D' THEN '上臘' ELSE COALESCE(TRIM("a"."名稱"), ' ') END, REPLACE(TRIM(CONCAT(TRIM("m"."ab底側"), TRIM("m"."ab底側二"), TRIM("m"."ab底側三"), TRIM("m"."ab底側四"))), '()', ''), '半成品', CASE WHEN COALESCE("b"."名稱", ' ') = ' ' THEN '' ELSE '#' END, COALESCE(TRIM("b"."名稱"), ' '), REPLACE("m"."預計投產日", '00000000', ''), RTRIM(CONCAT(' ', TRIM(CASE WHEN COALESCE(TRIM("c"."名稱"), ' ') = ' ' THEN ' ' ELSE CONCAT('＠', COALESCE(TRIM("c"."名稱無代碼"), ' ')) END)))), 'A材B材', 'AB材') AS "名稱", "m"."父節點", "m"."說明", "m"."半成品名稱" FROM "fil0039" AS "m" LEFT JOIN "viewfil310n" AS "a" ON "m"."製程代碼" = "a"."代碼" LEFT JOIN "viewfil310t" AS "b" ON "m"."工作代碼" = "b"."代碼" LEFT JOIN "viewfil310p" AS "c" ON "m"."機台代碼" = "c"."代碼");

