CREATE OR REPLACE VIEW "viewfil404zi" ("製程", "單別", "單號", "製令單別", "製令單號", "加工別", "開始時間", "結束時間", "總耗時") AS (/* 印刷~積層 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31A' THEN '印刷' WHEN "b"."製程代碼" = 'C32D' THEN '上臘' WHEN "b"."製程代碼" = 'C31B' THEN '淋膜' ELSE '積層' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' END AS "加工別", TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss') AS "開始時間", TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') AS "結束時間", CASE WHEN "b"."時間五" = '000000' THEN 0 ELSE (TO_DATE(CONCAT(TO_CHAR(CASE WHEN "b"."時間五" > "b"."時間一" THEN TO_DATE("a"."單據日期", 'yyyymmdd') ELSE TO_DATE("a"."單據日期", 'yyyymmdd') + 1 END, 'yyyymmdd'), "b"."時間五"), 'yyyymmddhh24miss') - TO_DATE(CONCAT(TRIM("a"."單據日期"), "b"."時間一"), 'yyyymmddhh24miss')) * 24 END AS "總耗時" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "viewfil4030" AS "c" ON "a"."歸屬類別" = "c"."製令單別" AND "a"."歸屬編號" = "c"."製令單號" WHERE "a"."單據類別" = 'C41' AND ("b"."製程代碼" BETWEEN 'C31A' AND 'C31D' OR "b"."製程代碼" = 'C32D') AND ("b"."時間一" BETWEEN '000000' AND '235959') AND ("b"."時間五" BETWEEN '000000' AND '235959') UNION ALL /* 裁切~成捲 */ SELECT CAST(CASE WHEN "b"."製程代碼" = 'C31D' THEN '裁切' WHEN "b"."製程代碼" = 'C31E' THEN '製袋' WHEN "b"."製程代碼" = 'C31F' THEN '氣閥' WHEN "b"."製程代碼" = 'C31G' THEN '鐵條' ELSE '成捲' END AS TEXT) AS "製程", "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."歸屬類別" AS "製令單別", "a"."歸屬編號" AS "製令單號", CASE WHEN "b"."交貨日期_次批" = 'A' THEN 'A材' WHEN "b"."交貨日期_次批" = 'B' THEN 'B材' WHEN "b"."交貨日期_次批" = 'C' THEN '底邊' WHEN "b"."交貨日期_次批" = 'D' THEN 'A側' WHEN "b"."交貨日期_次批" = 'E' THEN 'B側' ELSE ' ' EN