CREATE OR REPLACE VIEW "viewfilf061" ("單別", "單號", "類別代碼", "類別說明", "公司代碼", "公司名稱", "單據日期", "簽核系統", "備註", "倉管員", "倉管員姓名", "流水編號", "填表人", "填表人姓名", "填表日", "最後更新者", "更新者姓名", "製程代碼", "製程名稱", "工站代碼", "工站名稱", "製程工站", "機台代碼", "機台名稱", "最後更新日", "簽核狀態") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."稅別" AS "類別代碼", CASE WHEN "a"."稅別" = 'A' THEN '委外' ELSE '廠內' END AS "類別說明", "a"."公司代碼", COALESCE("e"."全名", ' ') AS "公司名稱", "a"."單據日期", "a"."簽核系統", "a"."備註", "a"."業務員" AS "倉管員", COALESCE("d"."員工姓名", ' ') AS "倉管員姓名", "a"."流水編號", "a"."填表人", COALESCE("z1"."員工姓名", ' ') AS "填表人姓名", "a"."填表日", "a"."最後更新者", COALESCE("z2"."員工姓名", ' ') AS "更新者姓名", "b"."製程代碼", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."製程名稱", ' ') ELSE CASE WHEN "b"."製程代碼" = 'M' THEN '原料' WHEN "b"."製程代碼" = 'N' THEN '物料' WHEN "b"."製程代碼" = 'O' THEN '其他' WHEN "b"."製程代碼" = 'S' THEN '半成品' WHEN "b"."製程代碼" = 'P' THEN '版銅' ELSE '錯誤' END END AS "製程名稱", "b"."工站代碼", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."名稱", ' ') ELSE COALESCE("j"."名稱", ' ') END AS "工站名稱", CASE WHEN "a"."稅別" = 'A' THEN COALESCE("i"."製程工站", ' ') ELSE CONCAT(COALESCE("j"."名稱", ' '), '(', CASE WHEN "b"."製程代碼" = 'M' THEN '原料' WHEN "b"."製程代碼" = 'N' THEN '物料' WHEN "b"."製程代碼" = 'O' THEN '其他' WHEN "b"."製程代碼" = 'S' THEN '半成品' WHEN "b"."製程代碼" = 'P' THEN '版銅' ELSE '錯誤' END, ')') END AS "製程工站", "b"."機台代碼", COALESCE("h"."名稱", ' ') AS "機台名稱", "a"."最後更新日", COALESCE("z3"."簽核狀態", '0') AS "簽核狀態" FROM "fil0030" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" LEFT JOIN "fil0010" AS "d" ON "a"."業務員" = "d"."員工編號" LEFT JOIN "viewfil0011" AS "e" ON "a"."公司代碼" = "e"."代碼" LEFT JOIN "fil0037" AS "g" ON "a"."單據類別" = "g"."製令單別" AND "a"."單據編號" = "g"."製令單號" AND "g"."材料序號" = 0 /* 委外盤點.工站 */ LEFT JOIN "viewfil310p" AS "h" ON "b"."機台代碼" = "h"."代碼" LEFT JOIN "viewfil310o" AS "i" ON "b"."工站代碼" = "i"."代碼" /* 廠內盤點.物料大類 */ LEFT JOIN "viewfil310b" AS "j" ON "b"."工站代碼" = "j"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."填表人" = "z1"."員工編號" LEFT JOIN "fil0010" AS "z2" ON "a"."最後更新者" = "z2"."員工編號" LEFT JOIN "viewofobjproperties" AS "z3" ON "a"."流水編號" = "z3"."單據流水號" WHERE "a"."單據類別" = 'F35');

