CREATE OR REPLACE VIEW "viewfilf0w0" ("製程代碼", "製程名稱", "工站代碼", "工站名稱", "製程工站", "產品編號", "品名", "規格", "氣閥代碼", "製令單號", "製造日期", "加工數量", "回廠數量", "退回數量", "調整數量", "生產數量", "報廢數量", "合理剔除數", "結存數量", "待生產數量", "待回廠數量", "結案") AS (SELECT "a"."製程代碼", "d"."製程名稱", "a"."工站代碼", "d"."名稱" AS "工站名稱", "d"."製程工站", "c"."產品編號", "c"."產品名稱" AS "品名", "c"."展開尺寸" AS "規格", "c"."加工項目_氣閥代碼" AS "氣閥代碼", "a"."製令單號", "a"."填表日" AS "製造日期", "a"."加工數量", "a"."回廠數量", "a"."退回數量", "a"."調整數量", COALESCE("b"."生產數量", 0) AS "生產數量", COALESCE("b"."報廢數量", 0) AS "報廢數量", COALESCE("b"."合理剔除數", 0) AS "合理剔除數", "a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0) AS "結存數量", CASE WHEN ("a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0)) = 0 THEN 0 ELSE "a"."加工數量" - "a"."退回數量" - COALESCE("b"."生產數量", 0) - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0) END AS "待生產數量", CASE WHEN ("a"."加工數量" - "a"."回廠數量" - "a"."退回數量" + "a"."調整數量" - COALESCE("b"."報廢數量", 0) - COALESCE("b"."合理剔除數", 0)) = 0 THEN 0 ELSE COALESCE("b"."生產數量", 0) - "a"."回廠數量" END AS "待回廠數量", CASE WHEN ("a"."加工數量" - "a"."退回數量") = (COALESCE("b"."報廢數量", 0) + COALESCE("b"."生產數量", 0) + COALESCE("b"."合理剔除數", 0)) OR (("a"."加工數量" - "a"."退回數量") IS NULL AND (COALESCE("b"."報廢數量", 0) + COALESCE("b"."生產數量", 0) + COALESCE("b"."合理剔除數", 0)) IS NULL) THEN 1 ELSE 0 END AS "結案" FROM (SELECT "b"."製程代碼", "b"."工站代碼", "a"."廠客品號" AS "製令單號", MIN(COALESCE("d"."填表日", "e"."填表日")) AS "填表日", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 1 ELSE 0 END ELSE 0 END) AS "回廠數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" * CASE WHEN "a"."logical1" = 0 THEN 0 ELSE 1 END ELSE 0 END) AS "退回數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量" FROM "fil0040" AS "a" INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0037" AS "c" ON "a"."單據類別" = "c"."製令單別" AND "a"."單據編號" = "c"."製令單號" AND "c"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("c"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') LEFT JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" AND "d"."單據類別" = 'F11' LEFT JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' GROUP BY "b"."製程代碼", "b"."工站代碼", "a"."廠客品號") AS "a" INNER JOIN "viewfil310o" AS "d" ON "a"."工站代碼" = "d"."代碼" INNER JOIN "fil0032" AS "c" ON "c"."製令單別" = 'C11' AND "c"."製令單號" = "a"."製令單號" LEFT JOIN "viewfilf014" AS "b" ON "a"."工站代碼" = "b"."工站代碼" AND "a"."製令單號" = "b"."製令單號");

