CREATE OR REPLACE VIEW "viewfilf0w4b_1" ("料號", "製程代碼", "工站代碼", "加工數量", "回廠數量", "耗用數量", "報廢數量", "調整數量", "結存數量") AS (SELECT "a"."產品編號" AS "料號", "b"."製程代碼", "b"."工站代碼", SUM(CASE WHEN "a"."單據類別" = 'F11' THEN "a"."贈品數量" ELSE 0 END) AS "加工數量", SUM(CASE WHEN "a"."單據類別" = 'F21' THEN "a"."贈品數量" ELSE 0 END) AS "回廠數量", 0 AS "耗用數量", 0 AS "報廢數量", SUM(CASE WHEN "a"."單據類別" = 'F32' THEN "a"."贈品數量" ELSE 0 END) AS "調整數量", SUM("a"."贈品數量" * CASE WHEN "a"."單據類別" = 'F11' THEN 1 WHEN "a"."單據類別" = 'F21' THEN -1 WHEN "a"."單據類別" = 'F32' THEN 1 ELSE -1 END) AS "結存數量" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewofobjproperties" AS "d1" ON "d"."流水編號" = "d1"."單據流水號" /* 料號 */ INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."產品類別" BETWEEN 'M' AND 'P' INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" /* 簽收 */ INNER JOIN "fil0037" AS "f" ON "a"."單據類別" = "f"."製令單別" AND "a"."單據編號" = "f"."製令單號" AND "f"."材料序號" = 0 AND ((COALESCE("dbms_lob".getlength("f"."圖檔"), 0) > 0) OR "a"."單據類別" = 'F32') /* 填單日 */ INNER JOIN "viewfilf013" AS "h" ON "h"."工站代碼" = "b"."工站代碼" AND "h"."批號" = "c"."批號" AND CASE WHEN "d1"."送簽日時" IS NULL THEN "d"."填表日" ELSE "d1"."送簽日時" END >= "h"."填表日" INNER JOIN "fil1014" AS "i" ON "i"."代碼類別" = '工站代碼' AND "b"."工站代碼" = "i"."系統代碼" WHERE "a"."單據類別" BETWEEN 'F11' AND 'F32' AND "a"."單據類別" <> 'F31' AND "a"."異動日期" >= "i"."日期" GROUP BY "a"."產品編號", "b"."製程代碼", "b"."工站代碼");

