CREATE OR REPLACE VIEW "viewfilh010" ("年月", "申請人", "假別", "請假時數", "請假扣薪", "假別轉換") AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "b"."申請人", "b"."假別", SUM("a"."異動數量") AS "請假時數", SUM(CASE WHEN "d"."扣點" = 0 THEN "a"."異動數量" * (CAST("e"."本薪" AS DOUBLE PRECISION) / (30 * 8) * "d"."扣薪") ELSE "a"."異動數量" * (CAST("e"."本薪" AS DOUBLE PRECISION) / (30 * 8 * 2)) * "d"."扣點" + (CAST("a"."異動數量" AS DOUBLE PRECISION) / 8 * ("e"."出勤日支" * "d"."扣點")) END) AS "請假扣薪", SUM(CASE WHEN "b"."假別" <> "b"."請假假別" THEN "a"."異動數量" ELSE 0 END) AS "假別轉換" FROM "fil0040" AS "a" INNER JOIN "hrfil1031" AS "b" ON "b"."單號" = "a"."單據編號" AND "b"."單別" = "a"."單據類別" LEFT JOIN "hrfil2006" AS "c" ON "b"."申請人" = "c"."員工編號" AND ORA_SUBSTR("a"."異動日期", 1, 6) = ORA_SUBSTR("c"."年月", 1, 6) LEFT JOIN "viewfil3801" AS "d" ON "d"."代碼" = "b"."假別" LEFT JOIN "hrfil2001" AS "e" ON "e"."員工編號" = "b"."申請人" AND ORA_SUBSTR("a"."異動日期", 1, 6) = "e"."年月" LEFT JOIN "viewfilh001" AS "z" ON "z"."單別" = "a"."單據類別" AND "z"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "z1" ON "z1"."單別" = "a"."單據類別" AND "z1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' AND "z"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "z1"."簽核狀態" = 'E' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "b"."申請人", "b"."假別");

