CREATE OR REPLACE VIEW "viewfilh014" ("年月", "申請人", "請假時數合計", "伙食扣假") AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數合計", SUM(CASE WHEN "a"."異動數量" > 4 THEN 1 ELSE 0.5 END) AS "伙食扣假" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" WHERE "a"."單據類別" = 'H01' AND "b"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "b1"."簽核狀態" = 'E' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END);

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilh015" ("年月", "申請人", "請假扣支", "請假時數", "出勤扣點", "伙食扣支") AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."申請人", "f"."請假扣支" AS "請假扣支", SUM("a"."請假時數") AS "請假時數", SUM("a"."出勤扣點") AS "出勤扣點", SUM(CAST("a"."伙食扣支時數" * "c"."伙食津貼" AS DOUBLE PRECISION) / 30) AS "伙食扣支" FROM (SELECT "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END AS "申請人", SUM("a"."異動數量") AS "請假時數", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2.01 AND 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END * 0.5 WHEN "a"."異動數量" > 4 THEN CASE WHEN CASE WHEN "a"."單據類別" = 'H01' THEN "b"."假別名稱" ELSE "b1"."假別名稱" END = '事假' THEN 2 ELSE 1 END ELSE 0 END, 0)) AS "出勤扣點", SUM(COALESCE(CASE WHEN "a"."異動數量" BETWEEN 2.01 AND 4 THEN 0.5 WHEN "a"."異動數量" > 4 THEN 1 ELSE 0 END, 0)) AS "伙食扣支時數" FROM "fil0040" AS "a" LEFT JOIN "viewfilh001" AS "b" ON "b"."單別" = "a"."單據類別" AND "b"."單號" = "a"."單據編號" LEFT JOIN "viewfilh018" AS "b1" ON "b1"."單別" = "a"."單據類別" AND "b1"."單號" = "a"."單據編號" WHERE ("a"."單據類別" = 'H01' AND "b"."簽核狀態" = 'E' OR "a"."單據類別" = 'H05' AND "b1"."簽核狀態" = 'E') GROUP BY "a"."異動日期", CASE WHEN "a"."單據類別" = 'H01' THEN "b"."申請人" ELSE "b1"."申請人" END) AS "a" LEFT JOIN "hrfil2001" AS "c" ON "c"."員工編號" = "a"."申請人" AND ORA_SUBSTR("a"."異動日期", 1, 6) = "c"."年月" LEFT JOIN "hrfil2006" AS "e" ON "a"."申請人" = "e"."員工編號" AND ORA_SUBSTR("a"."異動日期", 1, 6) = ORA_SUBSTR("e"."年月", 1, 6) LEFT JOIN (SELECT "a"."年月", "a"."申請人", SUM("a"."請假扣薪") AS "請假扣支" FROM "viewfilh010" AS "a" GROUP BY "a"."年月", "a"."申請人") AS "f" ON "f"."年月" = ORA_SUBSTR("a"."異動日期", 1, 6) AND "f"."申請人" = "a"."申請人" GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."申請人", "f"."請假扣支");

