CREATE OR REPLACE VIEW "viewfilh026" ("作業人員", "年月", "件數", "加工費") AS (SELECT "d"."產品編號" AS "作業人員", ORA_SUBSTR("c"."匯率日期", 1, 6) AS "年月", MAX("a"."數字一") AS "件數", SUM(ROUND("a"."數字一" * COALESCE(CASE WHEN "e"."製程代碼" = 'C31G' THEN "b"."鐵條加工單價" ELSE "b"."氣閥加工單價" END, 0), 0)) AS "加工費" FROM "fil0037" AS "a" INNER JOIN "fil0031" AS "e" ON "e"."單別" = "a"."相關單別" AND "e"."單號" = "a"."相關單號" INNER JOIN "fil0030" AS "g" ON "g"."單據類別" = "e"."單別" AND "g"."單據編號" = "e"."單號" INNER JOIN "fil0032" AS "b" ON "b"."製令單別" = "g"."歸屬類別" AND "b"."製令單號" = "g"."歸屬編號" INNER JOIN "fil0030" AS "c" ON "a"."製令單別" = "c"."單據類別" AND "a"."製令單號" = "c"."單據編號" INNER JOIN "fil0040" AS "d" ON "a"."製令單別" = "d"."單據類別" AND "a"."製令單號" = "d"."單據編號" AND "a"."材料序號" = "d"."單據序號" INNER JOIN "viewofobjproperties" AS "g_2" ON "c"."流水編號" = "g_2"."單據流水號" WHERE "a"."製令單別" = 'H03' AND "a"."屬性" = '4' AND "g_2"."簽核狀態" = 'E' AND "d"."logical1" = 1 GROUP BY "d"."產品編號", ORA_SUBSTR("c"."匯率日期", 1, 6));

