CREATE OR REPLACE VIEW "viewfilm017sa" ("批號", "庫存數") AS (SELECT "a"."批號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."條碼" AS "批號", "a"."庫存結算數" AS "異動數" FROM "fil0043" AS "a" UNION ALL /* 盤點調整 */ SELECT "c"."批號", ("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."單據類別" = 'F32' AND "c"."批號" <> ' ' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 驗收/入庫/調整/退出 */ SELECT "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" WHEN "a"."單據類別" = 'E12' THEN "a"."數值2" WHEN "a"."單據類別" = 'E13' THEN "a"."數值2" ELSE ("a"."異動數量" + "a"."贈品數量") END AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "b"."流水編號" WHERE "a"."入料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."異動日期" >= "f"."結算日期" UNION ALL /* 前製程日報領料 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", ("a"."異動數量") * -1 AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."異動數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" < 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報領用退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."單據序號" >= 500 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' AND "a"."logical1" = 0 AND "a"."退庫數量" > 0 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 前製程日報沿用 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = CAST("c"."文數字4" AS TEXT) WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" BETWEEN 'C31B' AND 'C31C') AND "c"."文數字4" <> ' ' AND "a"."logical1" = 1 AND "b"."單據日期" >= "f"."結算日期" UNION ALL /* 印刷日報退庫 */ SELECT CAST("c"."文數字4" AS TEXT) AS "批號", "a"."退庫數量" AS "異動數" FROM "fil0040" A