"a"."單據日期" >= "f"."結算日期" UNION ALL /* 裁切材料退庫 */ SELECT "a"."廠客單號" AS "批號", "c"."數值1" AS "異動數" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."廠客單號" WHERE "a"."單據類別" = 'E13' AND "a"."廠客單號" <> ' ' AND "c"."數值1" > 0 AND COALESCE("d"."簽核狀態", ' ') <> 'A' AND "a"."單據日期" >= "f"."結算日期" UNION ALL /* 氣閥鐵條領用2 */ SELECT "c"."文數字2" AS "批號", ("c"."數值2") * -1 AS "異動數" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."文數字2" WHERE "a"."單據類別" = 'C41' AND "c"."數值2" > 0 AND "d"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "a"."異動類別" = 'A' AND "c"."文數字2" <> ' ' AND "a"."異動日期" >= "f"."結算日期" /* 期初庫存 */ UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "b"."批號", ("a"."異動數量" - "a"."退庫數量") * -1 FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "b"."批號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "b"."批號" <> ' ' AND "c1"."單據日期" >= "f"."結算日期") AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號" GROUP BY "a"."批號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm018s" ("單別", "單號", "序號", "異動類別", "異動日期", "料號", "批號", "最後更新日", "異動數", "來源") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別", "a"."異動日期", "f"."料號" AS "料號", "a"."批號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", "a"."來源" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."異動日期", "c"."批號", "a"."最後更新日", ("a"."異動數量" + "a"."贈品數量") AS "異動數", '盤點調整' AS "來源" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "c"."批號" WHERE "a"."單據類別" = 'F32' AND "c"."批號" <> ' ' UNION ALL /* 驗收,進料退出,材料入庫,調整,裁切材料入庫 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."異動日期", "c"."批號", "a"."最後更新日", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" WHEN "a"."單據類別" = 'E12' THEN "a"."數值2" WHEN "a"."單據類別" = 'E13' THEN "a"."數值2" ELSE ("a"."異動數量" + "a"."贈品數量") END AS "異動數", CASE WHEN "a"."單據類別" = 'D41' THEN '原材料.退料' WHEN "a"."單據類別" = 'E12' THEN '材料調整' WHEN "a"."單據類別" = 'E13' THEN '裁切.材料' ELSE '原材料.驗收' END AS "來源" FROM "fil0040" AS "a" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "b"."流水編號" WHERE "a"."入料註記" = 1 AND "a"."產品編號" <> ' ' AND "c"."批號" <> ' ' AND COALESCE("d"."簽核狀態", ' ') <> 'A' UNION ALL /* 前製程日報領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", ("a"."異動數量") * -1 AS "異動數", CASE WHEN "d"."製程代碼" = 'C31B' THEN CASE WHEN "a"."異動類別" = 'C' AND "c"."專案代號" <> ' ' THEN '沿用轉入' ELSE '領用' END WHEN "d"."製程代碼" = 'C31C' THEN CASE WHEN "a"."異動類別" = 'C' AND "c"."專案代號" <> ' ' THEN '沿用轉入' ELSE '領用' END ELSE '領用' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' UNION ALL /* 印刷日報退回 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", '退庫' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."退庫數量" > 0 AND "d"."製程代碼" = 'C31A' AND CAST("c"."文數字4" AS TEXT) <> ' ' UNION ALL /* 前製程日報退回 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", '退庫' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" = 'C31B' OR "d"."製程代碼" = 'C31C' OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "c"."文數字4" <> ' ' UNION ALL /* 前製程日報沿用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", CAST("c"."文數字4" AS TEXT) AS "批號", "a"."最後更新日", "a"."退庫數量" AS "異動數", CASE WHEN "a"."logical1" = 1 THEN '退庫沿用' ELSE '退庫' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."退庫數量" > 0 AND ("d"."製程代碼" BETWEEN 'C31B' AND 'C31C') AND "c"."文數字4" <> ' ' UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."批號" AS "批號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", '領用' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "c"."批號" <> ' ' UNION ALL /* 製袋日報退庫_沿用 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "b"."單據日期", "c"."批號" AS "批號", "a"."最後更新日", "a"."贈品數量" AS "異動數", CASE WHEN "a"."logical1" = 1 THEN '退庫沿用' ELSE '退庫' END AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" WHERE "a"."單據類別" = 'C41' AND "a"."贈品數量" > 0 AND "d"."製程代碼" = 'C31E' AND "a"."異動類別" = 'C' AND "c"."批號" <> ' ' UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動類別", "a"."單據日期", "a"."批號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", '領用' AS "來源" FROM "viewfilm018a" AS "a" UNION ALL /* 裁切材料領用 */ SELECT "a"."單據類別", "a"."單據編號", 0, ' ', "a"."單據日期", "a"."廠客單號" AS "批號", "a"."最後更新日", "a"."折讓" * -1 AS "異動數", '領用' AS "來源" FROM "fil0030" AS "a" /* 特殊欄位 */ INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" LEFT JOIN "viewofobjproperties" AS "d" ON "d"."單據流水號" = "a"."流水編號" WHERE "a"."單據類別" = 'E13