CREATE OR REPLACE VIEW "viewfilm021a" ("製程代碼", "年月", "製程日報人工時") AS (SELECT "a"."製程代碼", ORA_SUBSTR("a"."作業日期", 1, 6) AS "年月", SUM("a"."總耗時" * "a"."加工人數") AS "製程日報人工時" FROM "viewfilm201" AS "a" GROUP BY "a"."製程代碼", ORA_SUBSTR("a"."作業日期", 1, 6));

