CREATE OR REPLACE VIEW "viewfilm022a" ("年月", "日報總人工時", "分攤間接人工", "分攤直接人工") AS (SELECT ORA_SUBSTR("a"."作業日期", 1, 6) AS "年月", SUM("a"."總耗時" * "a"."加工人數") AS "日報總人工時", MAX(COALESCE("b"."分攤間接人工", 0)) AS "分攤間接人工", MAX(COALESCE("b"."分攤直接人工", 0)) AS "分攤直接人工" FROM "viewfilm201" AS "a" LEFT JOIN (SELECT ORA_SUBSTR("a"."年月", 1, 6) AS "年月", SUM(CASE WHEN "a"."成本類別" = 'B' THEN ("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") ELSE 0 END) AS "分攤間接人工", SUM(CASE WHEN "a"."成本類別" = 'A' THEN ("a"."本月應發金額" - "a"."事病假薪點" - "a"."遲到早退扣支" - "a"."調補扣支") ELSE 0 END) AS "分攤直接人工" FROM "viewfilhs02" AS "a" WHERE "a"."製程代碼" = ' ' AND ORA_SUBSTR("a"."年月", 1, 6) > '2025' GROUP BY ORA_SUBSTR("a"."年月", 1, 6)) AS "b" ON "b"."年月" = ORA_SUBSTR("a"."作業日期", 1, 6) WHERE ORA_SUBSTR("a"."作業日期", 1, 6) > '2025' GROUP BY ORA_SUBSTR("a"."作業日期", 1, 6));

