CREATE OR REPLACE VIEW "viewfilm101" ("單別", "單號", "序號", "異動日期", "年月", "料號", "最後更新日", "異動數", "異動單價", "異動金額", "來源", "製程代碼") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."年月", "a"."料號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", COALESCE("a"."異動單價", 0) AS "異動單價", COALESCE("a"."異動金額", 0) AS "異動金額", "a"."來源", "a"."製程代碼" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動日期", ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."贈品數量" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '1.期初庫存' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" WHERE "a"."單據類別" = 'F35' AND "a"."異動日期" > '2025' UNION ALL /* 進貨發票 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."數值4" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '2.本期進貨' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "c" ON "c"."單據流水號" = "b"."流水編號" WHERE "a"."單據類別" = 'D21' AND "b"."單據日期" > '2025' AND "a"."異動類別" = ' ' AND COALESCE("c"."簽核狀態", ' ') <> 'A' UNION ALL /* 退貨 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") * -1 AS "異動數", ("a"."異動單價") * -1 AS "異動單價", ("a"."異動金額") * -1 AS "異動金額", '2.本期進貨' AS "來源", "a"."單據類別" AS "製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" LEFT JOIN "viewofobjproperties" AS "c" ON "c"."單據流水號" = "b"."流水編號" WHERE "a"."單據類別" = 'D41' AND "b"."單據日期" > '2025' AND "a"."異動類別" = 'S' AND COALESCE("c"."簽核狀態", ' ') <> 'A' UNION ALL /* 日報領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", CAST("a"."前製程編號" AS TEXT) AS "料號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", COALESCE("e"."平均單價", 0) AS "異動單價", (("a"."異動數量" - "a"."退庫數量") * -1) * COALESCE("e"."平均單價", 0) AS "異動金額", '4.領料' AS "來源", "d"."製程代碼" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfilm104" AS "e" ON "e"."年月" = ORA_SUBSTR("b"."單據日期", 1, 6) AND "e"."料號" = "a"."前製程編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND (("d"."製程代碼" BETWEEN 'C31A' AND 'C31C') OR "d"."製程代碼" = 'C32D' OR "d"."製程代碼" = 'C31H' OR "d"."製程代碼" = 'C31K') AND "b"."單據日期" > '2025' AND "c"."文數字4" <> ' ' /* 期初庫存 */ UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."單據日期", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月", "f"."料號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", COALESCE("e"."平均單價", 0) AS "異動單價", ("a"."異動數" * -1 * COALESCE("e"."平均單價", 0)) AS "異動金額", '4.領料' AS "來源", "d"."製程代碼" FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" LEFT JOIN "viewfilm104" AS "e" ON "e"."年月" = ORA_SUBSTR("a"."單據日期", 1, 6) AND "e"."料號" = "f"."料號" WHERE "a"."單據日期" > '2025') AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號");

