CREATE OR REPLACE VIEW "viewfilm106" ("單別", "單號", "直接材料") AS (SELECT "a"."單別" AS "單別", "a"."單號" AS "單號", SUM("a"."異動金額") AS "直接材料" FROM "viewfilm101" AS "a" WHERE "a"."來源" = '4.領料' GROUP BY "a"."單別", "a"."單號");

