CREATE OR REPLACE VIEW "viewfilm111" ("單別", "單號", "序號", "異動日期", "年月", "料號", "最後更新日", "異動數", "異動單價", "異動金額", "來源") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動日期", "a"."年月", "a"."料號", "a"."最後更新日", COALESCE("a"."異動數", 0) AS "異動數", COALESCE("a"."異動單價", 0) AS "異動單價", COALESCE("a"."異動金額", 0) AS "異動金額", "a"."來源" FROM (SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."異動日期", ORA_SUBSTR("a"."異動日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", "a"."贈品數量" AS "異動數", "a"."異動單價" AS "異動單價", "a"."異動金額" AS "異動金額", '1.期初庫存' AS "來源" FROM "fil0040" AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'F35' AND "e"."物料大類" = 'C10' UNION ALL /* 客供品條碼入庫 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") AS "異動數", ("a"."異動單價") AS "異動單價", ("a"."異動金額") AS "異動金額", '2.本期進貨' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'D51' AND "a"."異動類別" = ' ' AND "e"."物料大類" = 'C10' UNION ALL /* 退貨 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."數值4") * -1 AS "異動數", ("a"."異動單價") * -1 AS "異動單價", ("a"."異動金額") * -1 AS "異動金額", '2.本期進貨' AS "來源" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'D52' AND "a"."異動類別" = 'S' AND "e"."物料大類" = 'C10' UNION ALL /* 領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "b"."單據日期", ORA_SUBSTR("b"."單據日期", 1, 6) AS "年月", "a"."產品編號" AS "料號", "a"."最後更新日", ("a"."異動數量" - "a"."退庫數量") * -1 AS "異動數", 0 AS "異動單價", 0 AS "異動金額", '4.領料' FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."領料註記" = 1 AND "c"."文數字4" <> ' ' AND "e"."物料大類" = 'C10' /* 期初庫存 */ UNION ALL /* 製袋裁切領料 */ SELECT "a"."單據類別", "a"."單據編號", "a"."單據序號", "a"."單據日期", ORA_SUBSTR("a"."單據日期", 1, 6) AS "年月", "f"."料號", "a"."最後更新日", "a"."異動數" * -1 AS "異動數", 0 AS "異動單價", 0 AS "異動金額", '4.領料' FROM "viewfilm018a" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" INNER JOIN "viewfil1012" AS "e" ON "f"."料號" = "e"."產品編號" WHERE "e"."物料大類" = 'C10') AS "a" INNER JOIN "viewfil4a4l" AS "b" ON "b"."產品編號" = "a"."料號" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號");

