CREATE OR REPLACE VIEW "viewfilm204" ("製程代碼", "年月", "製程直接人工每人工時", "製程製造費用每人工時") AS WITH "temp1" AS (SELECT "m"."製程代碼", "m"."年月", CASE WHEN COALESCE("a"."製程日報人工時", 0) = 0 THEN 0 ELSE CAST(COALESCE("c"."分攤直接人工", 0) AS DOUBLE PRECISION) / COALESCE("a"."製程日報人工時", 0) END AS "製程直接人工每人工時", CASE WHEN COALESCE("a"."製程日報人工時", 0) = 0 THEN 0 ELSE CAST((CASE WHEN COALESCE("b"."日報總人工時", 0) = 0 THEN 0 ELSE CAST(COALESCE("b"."分攤間接人工", 0) * COALESCE("a"."製程日報人工時", 0) AS DOUBLE PRECISION) / COALESCE("b"."日報總人工時", 0) END) AS DOUBLE PRECISION) / COALESCE("a"."製程日報人工時", 0) END AS "製程製造費用每人工時" FROM "fil1051" AS "m" /* 製程人工時月彙總 */ LEFT JOIN "viewfilm021a" AS "a" ON "m"."年月" = "a"."年月" AND "m"."製程代碼" = "a"."製程代碼" /* 人工時月彙總 */ LEFT JOIN "viewfilm022a" AS "b" ON "b"."年月" = "m"."年月" /* 製程實際直接人工 */ LEFT JOIN "viewfilm202" AS "c" ON "c"."年月" = "m"."年月" AND "c"."製程代碼" = "m"."製程代碼") SELECT "製程代碼", "年月", "製程直接人工每人工時", "製程製造費用每人工時" FROM "temp1";

