CREATE OR REPLACE VIEW "viewfilr010d" ("單別", "單號", "序號", "加工別", "製令單別", "製令單號", "產品編號", "產品名稱", "材質結構", "成品規格", "生產總量", "異常數量", "單位代碼", "單位名稱", "異常單位代碼", "異常單位名稱", "交貨日期", "客戶編號", "特採數量", "報廢數量", "全批", "生產中", "異常數量待確認", "特採數量待確認", "報廢數量待確認", "尚未生產", "建檔日期", "建檔時間", "流水編號", "主檔流水編號", "最後更新者", "更新者姓名", "最後更新日") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動類別" AS "加工別", "a"."前置單別" AS "製令單別", "a"."前置單號" AS "製令單號", "b"."產品編號", "b"."產品名稱", "a"."備註說明" AS "材質結構", COALESCE("d"."規格", ' ') AS "成品規格", "a"."異動數量" AS "生產總量", "a"."贈品數量" AS "異常數量", "a"."單位代碼", COALESCE("f1"."名稱", ' ') AS "單位名稱", "a"."相關代碼1" AS "異常單位代碼", COALESCE("f2"."名稱", ' ') AS "異常單位名稱", "a"."異動日期" AS "交貨日期", "c"."廠客編號" AS "客戶編號", "a"."數值1" AS "特採數量", "a"."數值2" AS "報廢數量", "a"."logical1" AS "全批", "a"."logical2" AS "生產中", "a"."logical3" AS "異常數量待確認", "a"."logical4" AS "特採數量待確認", "a"."logical5" AS "報廢數量待確認", "a"."領料註記" AS "尚未生產", "a"."預交日" AS "建檔日期", "a"."time1" AS "建檔時間", "a"."流水編號", "m"."流水編號" AS "主檔流水編號", "a"."最後更新者", COALESCE("z1"."員工姓名", ' ') AS "更新者姓名", "a"."最後更新日" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "m" ON "m"."單據類別" = "a"."單據類別" AND "m"."單據編號" = "a"."單據編號" INNER JOIN "fil0032" AS "b" ON "a"."前置單別" = "b"."製令單別" AND "a"."前置單號" = "b"."製令單號" INNER JOIN "fil0030" AS "c" ON "a"."前置單別" = "c"."單據類別" AND "a"."前置單號" = "c"."單據編號" LEFT JOIN "viewfil1012" AS "d" ON REGEXP_SUBSTR("b"."產品編號", '[^/]+', 1, 1) = "d"."產品編號" LEFT JOIN "viewfil3103" AS "f1" ON "a"."單位代碼" = "f1"."代碼" LEFT JOIN "viewfil3103" AS "f2" ON "a"."相關代碼1" = "f2"."代碼" LEFT JOIN "fil0010" AS "z1" ON "a"."最後更新者" = "z1"."員工編號" WHERE "a"."單據類別" = 'R02');

