CREATE OR REPLACE VIEW "viewfilm001" ("月份", "倉庫代碼", "材料編號", "異動數量") AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "月份", "a"."倉庫代碼", "a"."材料編號", SUM("a"."異動數") AS "異動數量" FROM "viewfil2022" AS "a" GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."倉庫代碼", "a"."材料編號");

