CREATE OR REPLACE VIEW "viewfilm005" ("月份", "庫別代碼", "庫別名稱", "倉別代碼", "倉別名稱", "材料編號", "前期庫存", "本期異動", "期末庫存", "年月序") AS (SELECT "a"."月份", "a"."倉庫代碼" AS "庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", "a"."材料編號", COALESCE("a"."前期庫存", 0) AS "前期庫存", "a"."本期異動", COALESCE("a"."前期庫存", 0) + "a"."本期異動" AS "期末庫存", ROW_NUMBER() OVER (PARTITION BY "a"."材料編號", "a"."倉庫代碼" ORDER BY "a"."月份" DESC) AS "年月序" FROM (SELECT "a"."月份", "a"."倉庫代碼", "a"."材料編號", (SELECT SUM("b"."異動數量") FROM "viewfilm001" AS "b" WHERE "b"."材料編號" = "a"."材料編號" AND "b"."倉庫代碼" = "a"."倉庫代碼" AND "b"."月份" < "a"."月份") AS "前期庫存", "a"."異動數量" AS "本期異動" FROM "viewfilm001" AS "a") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm006" ("材料編號", "庫存數") AS (SELECT "a"."材料編號", SUM("a"."異動數") AS "庫存數" FROM "viewfil2022" AS "a" GROUP BY "a"."材料編號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm007" ("材料編號", "庫別代碼", "庫別名稱", "倉別代碼", "倉別名稱", "庫存數") AS (SELECT "a"."材料編號", "a"."庫別代碼", COALESCE("b"."名稱", ' ') AS "庫別名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("c"."名稱", ' ') AS "倉別名稱", "a"."庫存數" FROM (SELECT "a"."材料編號", "a"."倉庫代碼" AS "庫別代碼", SUM("a"."異動數") AS "庫存數" FROM "viewfil2022" AS "a" GROUP BY "a"."材料編號", "a"."倉庫代碼") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."庫別代碼" = "b"."代碼" LEFT JOIN "viewfil310r" AS "c" ON "b"."倉別代碼" = "c"."代碼");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm008s" ("材料編號", "品名", "規格", "庫存數") AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫存數" FROM (SELECT "f"."料號", SUM(GREATEST(COALESCE("a"."庫存數", 0), 0)) AS "庫存數" FROM "viewfilm017sa" AS "a" INNER JOIN "fil0043" AS "f" ON "f"."條碼" = "a"."批號" GROUP BY "f"."料號") AS "a" INNER JOIN "fil0012" AS "e" ON "e"."產品編號" = "a"."料號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm008sa" ("材料編號", "品名", "規格", "庫位", "庫存數") AS (SELECT "a"."料號" AS "材料編號", "e"."品名", "e"."規格", "a"."庫位", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."批號", "a"."料號", COALESCE("g"."目前庫位", ' ') AS "庫位", "a"."異動數" FROM "viewfilm018s" AS "a" INNER JOIN "viewfilm000s" AS "g" ON "g"."條碼" = "a"."批號") AS "a" INNER JOIN "viewfil1012" AS "e" ON "a"."料號" = "e"."產品編號" GROUP BY "a"."料號", "e"."品名", "e"."規格", "a"."庫位");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm008sc" ("材料編號", "品名", "規格", "庫存數") AS WITH "temp1" AS (SELECT "a"."產品編號" AS "材料編號", SUM(CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數" END) AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."物料大類" BETWEEN 'B10' AND 'B20' AND CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END >= "c"."盤點日期" /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND ("a"."單據類別" = 'D21' AND "a"."異動類別" = 'A' OR "a"."單據類別" <> 'D21') AND COALESCE("h"."簽核狀態", ' ') <> 'A' GROUP BY "a"."產品編號" UNION ALL /* 領料 */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."異動數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" INNER JOIN "fil0030" AS "e" ON "a"."單據類別" = "e"."單據類別" AND "a"."單據編號" = "e"."單據編號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" INNER JOIN "fil0012" AS "g" ON "a"."產品編號" = "g"."產品編號" AND "g"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "g"."盤點日期" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."異動數量" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0012" AS "d" ON "a"."產品編號" = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "d"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" UNION ALL /* 印刷日報領用 */ SELECT CAST("a"."前製程編號" AS TEXT) AS "材料編號", SUM(("a"."異動數量" - "a"."退庫數量") * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "fil0012" AS "d" ON CAST("a"."前製程編號" AS TEXT) = "d"."產品編號" AND "d"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "d"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動數量" > 0 AND "c"."製程代碼" = 'C31A' AND "a"."前製程編號" <> ' ' GROUP BY CAST("a"."前製程編號" AS TEXT) UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "d"."料號" AS "材料編號", SUM("b"."數值1" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "d"."料號" <> ' ' GROUP BY "d"."料號" UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "d"."料號" AS "材料編號", SUM("b"."數值2" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "fil0012" AS "e" ON "d"."料號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "d"."料號" <> ' ' GROUP BY "d"."料號" UNION ALL /* 發料回庫(-)
SELECT 
	A.產品編號 材料編號,
	SUM(A.贈品數量 * -1) 異動數
FROM 
	FIL0040 A
	INNER JOIN FIL0041 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號 AND A.單據序號 = B.序號
	INNER JOIN FIL0012 C ON A.產品編號 = C.產品編號 AND C.物料大類 between 'B10' and 'B20' AND  A.異動日期 >= C.盤點日期
	LEFT JOIN FIL0043 G ON B.批號 = G.條碼
WHERE
	A.單據類別 = 'C41' AND
	A.異動類別 = 'C' AND
	A.贈品數量 != 0 AND
	A.產品編號 != ' '
GROUP BY
	A.產品編號

UNION ALL
*/ /* 發料回庫(+) */ SELECT "a"."產品編號" AS "材料編號", SUM("a"."贈品數量" * 1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "c"."盤點日期" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND "a"."產品編號" <> ' ' GROUP BY "a"."產品編號" /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號" AS "材料編號", SUM(("a"."異動數量" + "a"."贈品數量")) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" AND "e"."物料大類" BETWEEN 'B10' AND 'B20' AND "a"."異動日期" >= "e"."盤點日期" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' GROUP BY "a"."產品編號") SELECT "e"."產品編號" AS "材料編號", "e"."品名", "e"."規格", SUM(COALESCE("a"."異動數", 0)) + MAX(COALESCE("e"."盤存數量", 0)) AS "庫存數" FROM "fil0012" AS "e" LEFT JOIN "temp1" AS "a" ON "a"."材料編號" = "e"."產品編號" WHERE "e"."物料大類" BETWEEN 'B10' AND 'B20' GROUP BY "e"."產品編號", "e"."品名", "e"."規格";

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm011" ("月份", "倉庫代碼", "材料編號", "批號", "異動數量") AS (SELECT ORA_SUBSTR("a"."異動日期", 1, 6) AS "月份", "a"."倉庫代碼", "a"."材料編號", "a"."批號", SUM("a"."異動數") AS "異動數量" FROM "viewfil2022" AS "a" WHERE "a"."批號" <> ' ' GROUP BY ORA_SUBSTR("a"."異動日期", 1, 6), "a"."倉庫代碼", "a"."材料編號", "a"."批號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm015" ("月份", "倉庫代碼", "倉庫名稱", "倉別代碼", "倉別名稱", "材料編號", "批號", "前期庫存", "本期異動", "期末庫存", "年月序") AS (SELECT "a"."月份", "a"."倉庫代碼", COALESCE("b"."名稱", ' ') AS "倉庫名稱", COALESCE("b"."倉別代碼", ' ') AS "倉別代碼", COALESCE("b"."倉別名稱", ' ') AS "倉別名稱", "a"."材料編號", "a"."批號", COALESCE("a"."前期庫存", 0) AS "前期庫存", "a"."本期異動", COALESCE("a"."前期庫存", 0) + "a"."本期異動" AS "期末庫存", ROW_NUMBER() OVER (PARTITION BY "a"."材料編號", "a"."批號", "a"."倉庫代碼" ORDER BY "a"."月份" DESC) AS "年月序" FROM (SELECT "a"."月份", "a"."倉庫代碼", "a"."材料編號", "a"."批號", (SELECT SUM("b"."異動數量") FROM "viewfilm011" AS "b" WHERE "b"."材料編號" = "a"."材料編號" AND "b"."批號" = "a"."批號" AND "b"."倉庫代碼" = "a"."倉庫代碼" AND "b"."月份" < "a"."月份") AS "前期庫存", "a"."異動數量" AS "本期異動" FROM "viewfilm011" AS "a") AS "a" LEFT JOIN "viewfil3106" AS "b" ON "a"."倉庫代碼" = "b"."代碼");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm016a" ("批號", "庫存數") AS (SELECT "a"."批號", SUM("a"."庫存數量") AS "庫存數" FROM (SELECT "a"."批號", SUM("a"."異動數量") AS "庫存數量" FROM "viewfilm011" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP, 'yyyymm') GROUP BY "a"."批號" UNION ALL SELECT "a"."批號", SUM("a"."庫存數量") FROM "fil5002" AS "a" WHERE "a"."月份" = TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm') GROUP BY "a"."批號") AS "a" GROUP BY "a"."批號");

-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm017" ("材料編號", "物料大類", "品名", "規格", "批號", "庫存數") AS (SELECT "a"."產品編號" AS "材料編號", "e"."物料大類", "e"."品名", "e"."規格", CASE WHEN "e"."批號管理" = 0 THEN '' ELSE "a"."批號" END AS "批號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."產品編號", "c"."批號", CASE WHEN "a"."單據類別" = 'D21' THEN "a"."數值4" ELSE ("a"."異動數量" + "a"."贈品數量") END * "b"."材料庫存參數" AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 特殊欄位 */ LEFT JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "fil0012" AS "e" ON "a"."產品編號" = "e"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ /* 簽核 */ LEFT JOIN "viewofobjproperties" AS "h" ON "h"."單據流水號" = "d"."流水編號" WHERE "a"."產品編號" <> ' ' AND CASE WHEN "e"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND COALESCE("h"."簽核狀態", ' ') <> 'A' AND CASE WHEN "a"."單據類別" = 'D21' THEN CASE WHEN "a"."異動類別" = 'A' THEN 0 ELSE 1 END ELSE 0 END = 0 UNION ALL /* 發料 */ SELECT "a"."產品編號", "c"."批號", "a"."異動數量" AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "fil0012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
