-- Oracle user_views
CREATE OR REPLACE VIEW "viewfilm020a" ("材料編號", "倉庫代碼", "批號", "庫存數") AS (SELECT "a"."產品編號" AS "材料編號", "a"."倉庫代碼", COALESCE(CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "f"."批號" END, ' ') AS "批號", SUM(("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數") AS "庫存數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 /* 主檔 */ INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" /* 品號檔 */ INNER JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" AND "c"."產品類別" BETWEEN 'M' AND 'P' /* 特殊欄位 */ LEFT JOIN "fil0041" AS "f" ON "a"."單據類別" = "f"."單別" AND "a"."單據編號" = "f"."單號" AND "a"."單據序號" = "f"."序號" WHERE "a"."產品編號" <> ' ' AND CASE WHEN "a"."異動日期" = '00000000' THEN "d"."單據日期" ELSE "a"."異動日期" END <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."倉庫代碼", COALESCE(CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "f"."批號" END, ' ') UNION ALL /* 領料 */ SELECT "a"."產品編號" AS "材料編號", "f"."庫位代碼" AS "倉庫代碼", CASE WHEN "g"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END, SUM("a"."異動數量") AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0031" AS "d" ON "a"."單據類別" = "d"."單別" AND "a"."單據編號" = "d"."單號" LEFT JOIN "viewfil310p" AS "f" ON "d"."機台代碼" = "f"."代碼" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "f"."庫位代碼", CASE WHEN "g"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "d"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", SUM("a"."異動數量" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c" ON "a"."單據類別" = "c"."單據類別" AND "a"."單據編號" = "c"."單據編號" INNER JOIN "viewfil1012" AS "d" ON "a"."產品編號" = "d"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."倉庫代碼", CASE WHEN "d"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "d"."料號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字1" END AS "批號", SUM("b"."數值1" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字1" = "d"."條碼" INNER JOIN "viewfil1012" AS "e" ON "d"."料號" = "e"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND "d"."料號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "d"."料號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字1" END UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "d"."料號" AS "材料編號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字2" END AS "批號", SUM("b"."數值2" * -1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "d" ON "b"."文數字2" = "d"."條碼" INNER JOIN "viewfil1012" AS "e" ON "d"."料號" = "e"."產品編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND "d"."料號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "d"."料號", "a"."倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "b"."文數字2" END UNION ALL /* 發料回庫(-)
SELECT 
	A.產品編號 材料編號,
	A.倉庫代碼,
	decode(C.批號管理,0,' ',B.批號) 批號,
	SUM(A.贈品數量 * -1) 庫存數
FROM 
	FIL0040 A
	INNER JOIN FIL0041 B ON A.單據類別 = B.單別 AND A.單據編號 = B.單號 AND A.單據序號 = B.序號
	INNER JOIN FIL0030 D ON A.單據類別 = D.單據類別 AND A.單據編號 = D.單據編號	
	LEFT JOIN VIEWFIL1012 C ON A.產品編號 = C.產品編號
WHERE
	A.單據類別 = 'C41' AND
	A.異動類別 = 'C' AND
	A.贈品數量 != 0 AND
	A.產品編號 != ' ' AND
	A.異動日期 <= TO_CHAR(SYSDATE - interval '1' month,'yyyymm')||'99'
GROUP BY 
	A.產品編號,
	A.倉庫代碼,
	decode(C.批號管理,0,' ',B.批號)

UNION ALL
*/ /* 發料回庫(+) */ SELECT "a"."產品編號", "a"."前置單別" AS "倉庫代碼", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END AS "批號", SUM("a"."贈品數量" * 1) AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND "a"."產品編號" <> ' ' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", "a"."前置單別", CASE WHEN "c"."批號管理" = 0 THEN ' ' ELSE "b"."批號" END /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號", ' ' AS "倉庫代碼", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END AS "批號", SUM("a"."異動數量" + "a"."贈品數量") AS "庫存數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' AND "a"."異動日期" <= CONCAT(TO_CHAR(CURRENT_TIMESTAMP - INTERVAL '1 MONTH', 'yyyymm'), '99') GROUP BY "a"."產品編號", CASE WHEN "e"."批號管理" = 0 THEN ' ' ELSE "c"."批號" END);

-- Oracle user_views
CREATE OR REPLACE VIEW "viewtemp01" ("材料編號", "庫存數") AS (SELECT "a"."產品編號" AS "材料編號", SUM(COALESCE("a"."異動數", 0)) AS "庫存數" FROM (SELECT "a"."產品編號", SUM(("a"."異動數量" + "a"."贈品數量") * "b"."材料庫存參數") AS "異動數" FROM "fil0040" AS "a" /* 庫存參數 */ INNER JOIN "viewfil0020" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "b"."材料庫存參數" <> 0 INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" LEFT JOIN "viewfil1012" AS "e" ON "a"."產品編號" = "e"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 F ON A.單位代碼 = F.從 AND E.單位代碼 = F.到
			*/ WHERE "a"."產品編號" <> ' ' AND CASE WHEN "e"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "a"."產品編號" UNION ALL /* 發料 */ SELECT "a"."產品編號", SUM("a"."異動數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" LEFT JOIN "viewfil1012" AS "g" ON "a"."產品編號" = "g"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 H ON A.單位代碼 = H.從 AND G.單位代碼 = H.到
			*/ WHERE "a"."單據類別" = 'C4M' AND "a"."產品編號" <> ' ' AND CASE WHEN "g"."批號管理" = 0 THEN '不分批號' ELSE "c"."批號" END <> ' ' AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "a"."產品編號" UNION ALL /* 材料領用,報廢,油墨領用 */ SELECT "a"."產品編號", SUM("a"."異動數量" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "viewfil1012" AS "c" ON "a"."產品編號" = "c"."產品編號" /* 單位換算
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" BETWEEN 'C' AND 'E' AND "a"."異動數量" <> 0 AND "a"."產品編號" <> ' ' AND CASE WHEN "c"."批號管理" = 0 THEN '不分批號' ELSE "b"."批號" END <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "a"."產品編號" UNION ALL /* 材料領用.氣閥.鐵條-批號1 */ SELECT "e"."料號" AS "產品編號", SUM("b"."數值1" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字1" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字1" <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "e"."料號" UNION ALL /* 材料領用.氣閥.鐵條-批號2 */ SELECT "e"."料號" AS "產品編號", SUM("b"."數值2" * -1) AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "viewfil1024" AS "e" ON "b"."文數字2" = "e"."條碼" WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'A' AND "c"."製程代碼" BETWEEN 'C31F' AND 'C31G' AND "b"."文數字2" <> ' ' AND TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "e"."料號" UNION ALL /* 發料回庫(+) */ SELECT "a"."產品編號", SUM("a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" INNER JOIN "fil0030" AS "c1" ON "a"."單據類別" = "c1"."單據類別" AND "a"."單據編號" = "c1"."單據編號" /* 單位換算
			LEFT JOIN VIEWFIL1012 C ON A.產品編號 = C.產品編號
			LEFT JOIN ViewFIL1017 E ON A.單位代碼 = E.從 AND C.單位代碼 = E.到
			*/ WHERE "a"."單據類別" = 'C41' AND "a"."異動類別" = 'C' AND "a"."贈品數量" <> 0 AND TO_CHAR("c1"."填表日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "a"."產品編號" /* 廠內盤點調整 */ UNION ALL SELECT "a"."產品編號", SUM("a"."異動數量" + "a"."贈品數量") AS "異動數" FROM "fil0040" AS "a" INNER JOIN "fil0030" AS "b" ON "a"."單據類別" = "b"."單據類別" AND "a"."單據編號" = "b"."單據編號" /* 特殊欄位 */ INNER JOIN "fil0041" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" AND "a"."單據序號" = "c"."序號" WHERE "a"."單據類別" = 'F32' AND "a"."異動類別" = '2' AND TO_CHAR("b"."填表日", 'YYYYMMDDHH24MISS') <= '20220628070000' GROUP BY "a"."產品編號") AS "a" GROUP BY "a"."產品編號");

