CREATE OR REPLACE VIEW "viewfil404e3" ("單別", "單號", "序號", "箱號", "數量", "報廢數量", "重量", "批號", "製令類別", "製令單號", "作業日期", "作業員一", "作業員二", "作業員三", "作業員一姓名", "作業員二姓名", "作業員三姓名", "單據數量", "單據重量", "來源", "標籤類別", "製袋", "氣閥", "鐵條", "異動", "重工", "品檢", "流水編號", "最後更新日時") AS (SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."贈品數量" ELSE "b"."數值14" END ELSE "b"."數值5" * -1 END, 0) AS "數量", 0 AS "報廢數量", COALESCE(CASE WHEN "c"."製程代碼" = 'C31E' THEN CASE WHEN "b"."數值14" = 0 THEN "a"."毛重" ELSE "a"."毛重" * (CAST("b"."數值14" AS DOUBLE PRECISION) / "a"."贈品數量") END ELSE "b"."數值5" * -1 * "g"."平均袋重" END, 0) AS "重量", CONCAT("d"."歸屬編號", '-', TRIM(TO_CHAR("a"."異動數量", '0000'))) AS "批號", "d"."歸屬類別" AS "製令類別", "d"."歸屬編號" AS "製令單號", "d"."單據日期" AS "作業日期", "g"."作業人員" AS "作業員一", "g"."作業員二" AS "作業員二", "g"."作業員三" AS "作業員三", "g"."作業人員姓名" AS "作業員一姓名", "g"."作業員二姓名" AS "作業員二姓名", "g"."作業員三姓名" AS "作業員三姓名", "a"."贈品數量" AS "單據數量", "a"."毛重" AS "單據重量", CASE WHEN "c"."製程代碼" = 'C31E' THEN CAST('製袋' AS TEXT) WHEN "c"."製程代碼" = 'C31G' THEN CAST('鐵條' AS TEXT) ELSE CAST('氣閥' AS TEXT) END AS "來源", "b"."標籤類別", 1 AS "製袋", CASE WHEN "c"."製程代碼" = 'C31F' THEN 1 ELSE 0 END AS "氣閥", CASE WHEN "c"."製程代碼" = 'C31G' THEN 1 ELSE 0 END AS "鐵條", 0 AS "異動", 0 AS "重工", 0 AS "品檢", "a"."流水編號", TO_CHAR("a"."最後更新日", 'YYYYMMDDHH24MISS') AS "最後更新日時" FROM "fil0040" AS "a" INNER JOIN "fil0041" AS "b" ON "a"."單據類別" = "b"."單別" AND "a"."單據編號" = "b"."單號" AND "a"."單據序號" = "b"."序號" LEFT JOIN "fil0031" AS "c" ON "a"."單據類別" = "c"."單別" AND "a"."單據編號" = "c"."單號" INNER JOIN "fil0030" AS "d" ON "a"."單據類別" = "d"."單據類別" AND "a"."單據編號" = "d"."單據編號" LEFT JOIN "viewfil404e7" AS "g" ON "d"."歸屬類別" = "g"."製令單別" AND "d"."歸屬編號" = "g"."製令單號" AND "a"."異動數量" = "g"."箱號" WHERE "a"."異動類別" = 'A' AND ("c"."製程代碼" = 'C31E' OR "c"."製程代碼" = 'C31F' OR "c"."製程代碼" = 'C31G') UNION ALL SELECT "a"."單據類別" AS "單別", "a"."單據編號" AS "單號", "a"."單據序號" AS "序號", "a"."異動數量" AS "箱號", COALESCE(C